insert into public.pokedex_kinds (id, ko_name, en_name) values
  ('national', '전국도감', 'National Pokédex'),
  ('kanto', '관동도감', 'Kanto Pokédex'),
  ('johto', '성도도감', 'Johto Pokédex')
insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 1, 1, true, '태어나서 얼마 동안 등의 씨앗에 담긴 영양을 섭취하며 자란다.', 'While it is young, it uses the nutrients that are stored in the seed on its back in order to grow.'),
  ('national', 2, 2, true, '햇빛을 받을수록 몸에 힘이 솟아나 등의 꽃봉오리가 자라난다.', 'Exposure to sunlight adds to its strength. Sunlight also makes the bud on its back grow larger.'),
  ('national', 3, 3, true, '꽃에서 황홀한 향기가 퍼져 나와 싸우는 자의 기분을 달래준다.', 'A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.'),
  ('national', 4, 4, true, '태어날 때부터 꼬리에 불꽃이 타오르고 있다. 불꽃이 꺼지면 생명도 다하고 만다.', 'From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.'),
  ('national', 5, 5, true, '싸움으로 기분이 고조되면 작열하는 불꽃을 뿜으며 주변을 태워버린다.', 'If it becomes agitated during battle, it spouts intense flames, incinerating its surroundings.'),
  ('national', 6, 6, true, '지상 1400m까지 날개를 사용해 날 수 있다. 고열의 불꽃을 내뿜는다.', 'Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.'),
  ('national', 7, 7, true, '위험해지면 등껍질에 손발을 감추고 몸을 지키면서 입에서 물을 내뿜는다.', 'When it feels threatened, it draws its limbs inside its shell and sprays water from its mouth.'),
  ('national', 8, 8, true, '탐스러운 귀와 꼬리를 능숙하게 다뤄서 수중에서의 밸런스를 유지한다.', 'It cleverly controls its furry ears and tail to maintain its balance while swimming.'),
  ('national', 9, 9, true, '등껍질의 로켓포에서 뿜어져 나오는 제트 수류는 두꺼운 철판도 뚫는다.', 'The rocket cannons on its shell fire jets of water capable of punching holes through thick steel.'),
  ('national', 10, 10, true, '다리는 짧지만 빨판으로 되어 있어 비탈길이나 벽에서도 지치지 않고 나아간다.', 'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.'),
  ('national', 11, 11, true, '단단한 껍질로 둘러싸여 있지만 안은 부드럽기 때문에 강한 공격에는 버티지 못한다.', 'Even though it is encased in a sturdy shell, the body inside is tender. It can’t withstand a harsh attack.'),
  ('national', 12, 12, true, '매일 꿀을 모으러 다닌다. 다리의 솜털에 꿀을 발라 둥지로 가지고 가는 습성이 있다.', 'It collects honey every day. It rubs honey onto the hairs on its legs to carry it back to its nest.'),
  ('national', 13, 13, true, '머리에 날카로운 침을 지니고 있다. 우거진 숲이나 풀밭에 숨어 끊임없이 풀잎을 먹고 있다.', 'Beware of the sharp stinger on its head. It hides in grass and bushes where it eats leaves.'),
  ('national', 14, 14, true, '스스로는 거의 움직일 수 없지만 위험해지면 침을 세워서 독을 뿜을 때도 있는 듯하다.', 'Able to move only slightly. When endangered, it may stick out its stinger and poison its enemy.'),
  ('national', 15, 15, true, '양손과 엉덩이에 있는 3개의 독침으로 상대를 찌르고 찌르고 또 찌르며 공격한다.', 'It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.'),
  ('national', 16, 16, true, '얌전한 성격이라 습격당해도 반격하지 않고 모래를 뿌려서 몸을 지키는 경우가 많다.', 'Very docile. If attacked, it will often kick up sand to protect itself rather than fight back.'),
  ('national', 17, 17, true, '어마어마한 체력의 소유자로 넓은 영역을 날아다니며 먼 곳까지 먹이를 찾으러 간다.', 'This Pokémon is full of vitality. It constantly flies around its large territory in search of prey.'),
  ('national', 18, 18, true, '마하2의 속도로 비행하여 먹이를 찾는다. 그 커다란 발톱은 무기로서도 두려움의 대상이다.', 'This Pokémon flies at Mach 2 speed, seeking prey. Its large talons are feared as wicked weapons.'),
  ('national', 19, 19, true, '2개의 이빨로 뭐든지 일단 갉고 본다. 1마리를 발견했다면 그곳에 40마리는 살고 있을 것이다.', 'Will chew on anything with its fangs. If you see one, you can be certain that 40 more live in the area.'),
  ('national', 20, 20, true, '뒷다리에 달린 작은 물갈퀴로 강을 헤엄치는 이유는 물속에 있는 먹이를 잡기 위해서다.', 'Its hind feet are webbed. They act as flippers, so it can swim in rivers and hunt for prey.'),
  ('national', 21, 21, true, '높이 나는 것에 서투르다. 영역을 지키기 위해 맹렬한 스피드로 날아다닌다.', 'Inept at flying high. However, it can fly around very fast to protect its territory.'),
  ('national', 22, 22, true, '옛날부터 살고 있는 포켓몬. 조금이라도 위험을 감지하면 하늘 높이 날아가 버린다.', 'A Pokémon that dates back many years. If it senses danger, it flies high and away, instantly.'),
  ('national', 23, 23, true, '성장할수록 점점 길어진다. 밤에는 나뭇가지에 몸을 돌돌 말고 쉰다.', 'The older it gets, the longer it grows. At night, it wraps its long body around tree branches to rest.'),
  ('national', 24, 24, true, '무서워 보이는 배의 무늬는 연구 결과 6종류 정도의 패턴이 확인되었다.', 'The frightening patterns on its belly have been studied. Six variations have been confirmed.'),
  ('national', 25, 25, true, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 26, 26, true, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('national', 27, 27, true, '땅을 파서 굴을 만든다. 땅속의 단단한 바위도 날카로운 발톱으로 부수며 파고들어 간다.', 'It burrows into the ground to create its nest. If hard stones impede its tunneling, it uses its sharp claws to shatter them and then carries on digging.'),
  ('national', 28, 28, true, '날카로운 발톱으로 찍으며 나무에 오른다. 아래에서 기다리는 모래두지들에게 나무열매를 떨어뜨려 나눠준다.', 'It climbs trees by hooking on with its sharp claws. Sandslash shares the berries it gathers, dropping them down to Sandshrew waiting below the tree.'),
  ('national', 29, 29, true, '단단한 앞니로 나무열매를 깨물어 먹는다. 뿔의 끝은 수컷보다 조금 둥그스름하다.', 'It uses its hard incisor teeth to crush and eat berries. The tip of a female Nidoran’s horn is a bit more rounded than the tip of a male’s horn.'),
  ('national', 30, 30, true, '무리에 위험이 닥치면 동료와 결속하여 초음파로 크게 합창한다.', 'If the group is threatened, these Pokémon will band together to assault enemies with a chorus of ultrasonic waves.'),
  ('national', 31, 31, true, '등의 가시 틈에 새끼를 태우고 달랜다. 이때는 독이 절대 나오지 않는다.', 'It pacifies offspring by placing them in the gaps between the spines on its back. The spines will never secrete poison while young are present.'),
  ('national', 32, 32, true, '몸집은 작지만 용맹한 성질을 지녔다. 친한 암컷을 지키기 위해 몸을 던져 과감히 싸운다.', 'Small but brave, this Pokémon will hold its ground and even risk its life in battle to protect the female it’s friendly with.'),
  ('national', 33, 33, true, '신경질적이고 호전적이다. 체내의 아드레날린이 증가하면 독소의 농도도 높아진다.', 'It’s nervous and quick to act aggressively. The potency of its poison increases along with the level of adrenaline present in its body.'),
  ('national', 34, 34, true, '힘이 센 포켓몬이다. 굵은 꼬리와 다이아몬드도 부수는 뿔로 호쾌하게 싸운다.', 'Nidoking prides itself on its strength. It’s forceful and spirited in battle, making use of its thick tail and diamond-crushing horn.'),
  ('national', 35, 35, true, '애교 있는 몸동작과 울음소리로 귀엽다고 많은 인기를 누리는 포켓몬. 그러나 좀처럼 눈에 띄지 않는다.', 'It can be found in quiet mountain areas on a full moon''s night. Its dancing and its tiny, faintly glowing wings confer upon it a lovely fairylike quality.'),
  ('national', 36, 36, true, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.'),
  ('national', 37, 37, true, '6개의 꼬리는 자라면서 털의 결이 좋아지며 아름다워진다. 안으면 살짝 따듯하다.', 'In its belly burns a fire, which Vulpix spits out in the form of fireballs. When young, this Pokémon has but one white tail. As the Pokémon matures, this single tail splits into six.'),
  ('national', 38, 38, true, '머리가 좋고 집념이 강하다. 장난으로 꼬리를 잡으면 1000년 동안 화를 입는다고 한다.', 'The coat of gleaming golden fur is quite magnificent. This species is said to store sacred power in its nine long tails and to live for a millennium.'),
  ('national', 39, 39, true, '목소리 파장을 자유자재로 바꾸어 들으면 반드시 잠드는 신비한 멜로디를 노래한다.', 'By freely changing the wavelength of its voice, Jigglypuff sings a mysterious melody sure to make any listener sleepy.'),
  ('national', 40, 40, true, '얇고 고운 털을 가졌다. 특히 이마에 동그랗게 말린 털은 하늘을 날 듯한 최고의 감촉을 지녔다.', 'It’s proud of its fur, which is fine and delicate. In particular, the curl on its forehead has a texture that’s perfectly heavenly.'),
  ('national', 41, 41, true, '볕이 들지 않는 동굴에 산다. 아침이 되면 동료들끼리 모여 서로의 온기를 나누면서 잔다.', 'Makes its home in gloomy caves. Atrophied eyes have left this Pokémon blind, so it scans its surroundings via sound waves that it emits from its mouth as it flies.'),
  ('national', 42, 42, true, '작은 다리로 능숙하게 걷는다. 자고 있는 먹이에게 살며시 다가가 이빨을 꽂아 피를 빨아먹는다.', 'It sinks its sharp fangs into other creatures and slurps up their blood. A closer look at the fangs reveals that they are hollow and akin to straws.'),
  ('national', 43, 43, true, '낮에는 태양을 피하기 위해 차가운 땅속에 들어가 있다. 달빛을 쬐어 성장한다.', 'During the day, it stays in the cold underground to avoid the sun. It grows by bathing in moonlight.'),
  ('national', 44, 44, true, '침처럼 보이는 달콤한 꿀은 매우 끈적거려서 묻으면 좀처럼 떨어지지 않는다.', 'What appears to be drool is actually sweet honey. It is very sticky and clings stubbornly if touched.'),
  ('national', 45, 45, true, '꽃잎이 클수록 많은 꽃가루를 만들어 내지만 머리가 무거워서 지쳐버린다고 한다.', 'The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.'),
  ('national', 46, 46, true, '구멍을 파서 나무뿌리로부터 영양을 섭취하지만 대부분은 등에 있는 버섯에게 빼앗긴다.', 'Sometimes seen at the foot of trees in humid forests. The mushrooms on its back—called tochukaso—are not present on infant specimens and instead emerge as Paras matures.'),
  ('national', 47, 47, true, '계속 진액을 빨아 먹혀서 이제는 벌레가 아니라 등에 있는 버섯이 생각하고 있는 듯하다.', 'Mushroom-lacking specimens of this Pokémon lie unmoving in the forest, lending credence to the hypothesis that the large mushroom is in control of Parasect''s actions.'),
  ('national', 48, 48, true, '레이더 역할을 하는 큰 눈은 밝은 곳에서 보면 작은 눈이 모여서 이루어진 것임을 알 수 있다.', 'Its large eyes act as radar. In a bright place, you can see that they are clusters of many tiny eyes.'),
  ('national', 49, 49, true, '날개의 인분은 몸에 묻으면 좀처럼 떨어지지 않는다. 게다가 거기에서 독성분이 스며든다.', 'The powdery scales on its wings are hard to remove from skin. They also contain poison that leaks out on contact.'),
  ('national', 50, 50, true, '얕은 땅속을 이동한다. 굴을 파며 다닌 곳은 지면이 솟아 있기 때문에 바로 알 수 있다.', 'It burrows through the ground at a shallow depth. It leaves raised earth in its wake, making it easy to spot.'),
  ('national', 51, 51, true, '지하 100km까지 파고들 수 있는 파워를 간직한 세쌍둥이 디그다. 땅 밑은 아무도 모른다.', 'These Diglett triplets dig over 60 miles below sea level. No one knows what it’s like underground.'),
  ('national', 52, 52, true, '이마의 금화가 더러워지지 않도록 바지런히 얼굴을 씻는다. 가라르의 나옹과는 사이가 나쁘다.', 'It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.'),
  ('national', 53, 53, true, '움직임은 우아하고 품위 있다. 야만스러운 나이킹과는 잘 맞지 않아 서로를 멸시한다.', 'Its elegant and refined behavior clashes with that of the barbaric Perrserker. The relationship between the two is one of mutual disdain.'),
  ('national', 54, 54, true, '스트레스가 쌓이면 두통이 심해진다. 강력한 염동력으로 주위를 압도한다.', 'Suffers perpetual headaches. If the agony grows too great, Psyduck''s latent power erupts, contrary to Psyduck''s intent. Ergo, I am exploring ways to ease the pain.'),
  ('national', 55, 55, true, '강을 더럽힌 사람을 물속으로 끌어들여 데려간다는 옛날이야기가 전해져 오고 있다.', 'Its body is strong, and it has webbing on its hands and feet. Golduck can swim easily through rough seas, clawing its way through the high waves.'),
  ('national', 56, 56, true, '몸이 가벼워 나무 위에서 생활한다. 사소한 일로 기분이 나빠져 주변에 있는 것에 덤벼든다.', 'An agile Pokémon that lives in trees. It angers easily and will not hesitate to attack anything.'),
  ('national', 57, 57, true, '주위에 아무도 없을 때만은 화를 내지 않고 있다. 그러나 그 모습을 보기가 어렵다.', 'It stops being angry only when nobody else is around. To view this moment is very difficult.'),
  ('national', 58, 58, true, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.'),
  ('national', 59, 59, true, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.'),
  ('national', 60, 60, true, '유속이 빠른 강에서는 두꺼운 입술을 흡반처럼 사용해 바위에 달라붙는다.', 'In rivers with fast-flowing water, this Pokémon will cling to a rock by using its thick lips, which act like a suction cup.'),
  ('national', 61, 61, true, '미끈미끈한 점액 형태의 땀을 흘린다. 적에게 붙잡혀도 스르륵 빠져나와 도망친다.', 'This Pokémon’s sweat is a slimy mucus. When captured, Poliwhirl can slither from its enemies’ grasp and escape.'),
  ('national', 62, 62, true, '헤엄뿐만 아니라 격투기도 특기다. 단련한 팔로 호쾌하게 펀치를 날린다.', 'Poliwrath is skilled at both swimming and martial arts. It uses its well-trained arms to dish out powerful punches.'),
  ('national', 63, 63, true, '잠이 든 상태에서 순간이동이 가능하다. 깊이 잠들수록 먼 곳으로 이동한다고 한다.', 'Spends 18 hours of the day sleeping. Even while asleep, Abra can control its psychic powers—should danger approach, the Pokémon will simply teleport away.'),
  ('national', 64, 64, true, '염동력의 위력은 절대적이다. 진화에 대비하여 이마에 있는 별에 사이코 파워를 비축하고 있다.', 'There are rumors that a child with mystical powers became a Kadabra; however, this remains unverified. I suspect that the spoon Kadabra holds enhances its brain waves.'),
  ('national', 65, 65, true, '강력한 초능력을 구사한다. 양손에 든 숟가락은 그 힘으로 만들어낸 것이라고 한다.', 'The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.'),
  ('national', 66, 66, true, '언제나 파워풀하다. 체력이 남아돌기 때문에 심심풀이로 바위를 들어 올리며 더 강해진다.', 'Though as small as a child, it has strength enough to easily throw a well-built adult. Striving to become ever stronger, Machop trains by carrying a Graveler on its shoulders.'),
  ('national', 67, 67, true, '지치지 않는 강인한 육체를 가졌다. 무거운 물건을 옮기는 등의 일을 돕는다.', 'A sturdy creature boasting a robust physique and boundless stamina. Loves training above all else and voluntarily assists with tasks such as construction and clearing land.'),
  ('national', 68, 68, true, '4개의 팔은 생각하는 것보다 빠르게 반사적으로 움직이며 여러 발의 펀치를 날린다.', 'In close combat, its four arms afford it offensive and defensive supremacy. In but a blink, this valiant Pokémon can overwhelm its foes with more than 1,000 blows from its fists.'),
  ('national', 69, 69, true, '온도가 높고 습기가 있는 장소를 좋아한다. 덩굴을 사용해 작은 벌레를 잡아먹는다.', 'Prefers hot and humid places. It ensnares tiny bugs with its vines and devours them.'),
  ('national', 70, 70, true, '배가 고프면 움직이는 것을 닥치는 대로 삼킨 다음 용해액으로 마무리한다.', 'When hungry, it swallows anything that moves. Its hapless prey is dissolved by strong acids.'),
  ('national', 71, 71, true, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Lures prey with the sweet aroma of honey. Swallowed whole, the prey is dissolved in a day, bones and all.'),
  ('national', 72, 72, true, '몸의 대부분이 수분이어서 바닷속에서는 물과 동화되어 매우 구분하기 힘들다.', 'They fire beams from the glassy, magenta orbs that resemble eyes atop their heads, and they drift in shallow seas. During low tide, they can sometimes be found on beaches, desiccated.'),
  ('national', 73, 73, true, '80개의 촉수는 자유롭게 늘어났다가 줄어든다. 그물처럼 펼쳐서 먹이를 잡고 독바늘로 찌른다.', 'It has 80 tentacles, each with a venomous tip. These tentacles are also extendible, lengthening when Tentacruel attempts to catch prey. Use caution.'),
  ('national', 74, 74, true, '산길 등에 많이 서식한다. 실수로 밟으면 화를 내므로 주의가 필요하다.', 'Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.'),
  ('national', 75, 75, true, '산길에서 자주 굴러다닌다. 가는 길에 무엇이 있든 전혀 신경 쓰지 않는다.', 'Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.'),
  ('national', 76, 76, true, '탈피한 직후에는 전체가 하얗고 부드럽지만 금방 공기와 접촉해서 단단해진다.', 'The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.'),
  ('national', 77, 77, true, '포니타에게 인정받으면 타오르는 갈기를 만져도 뜨거움을 느끼지 않게 된다.', 'These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.'),
  ('national', 78, 78, true, '가장 발이 빠른 날쌩마가 리더가 되어 무리가 갈 장소나 달리는 속도를 정한다.', 'Fiery mane aglow, Rapidash darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.'),
  ('national', 79, 79, true, '꼬리를 물에 담가두면 단맛이 배어 나오기 때문에 이를 미끼로 포켓몬을 유인해서 낚는다.', 'When this Pokémon’s tail is soaked in water, sweetness seeps from it. Slowpoke uses this trait to lure in and fish up other Pokémon.'),
  ('national', 80, 80, true, '셀러에게 물린 충격으로 두 발로 걸을 수 있게 되었다. 셀러가 떨어지면 야돈으로 돌아간다고 한다.', 'Being bitten by a Shellder shocked this Pokémon into standing on two legs. If the Shellder lets go, it seems Slowbro will turn back into a Slowpoke.'),
  ('national', 81, 81, true, '전기를 먹으며 살아간다. 좌우의 유닛에서 전기자석파를 방사하며 하늘을 난다.', 'A bizarre Pokémon with but a single eye embedded in an iron sphere. I suspect this creature levitates due to the magnetism it emits from its arms, which resemble horseshoe-shaped magnets.'),
  ('national', 82, 82, true, '강한 자력을 끊임없이 발산한다. 레어코일이 접근하면 대부분의 컴퓨터에 이상 현상이 발생한다.', 'Three Magnemite gathered to evolve into this Pokémon. The source of much vexation on my part, as its powerful magnetism destroys my research equipment.'),
  ('national', 83, 83, true, '식물의 줄기로 싸운다. 줄기를 휘두르는 방식에 따라 몇 종류의 유파가 있는 듯하다.', 'They use a plant stalk as a weapon, but not all of them use it in the same way. Several distinct styles of stalk fighting have been observed.'),
  ('national', 84, 84, true, '날개가 짧아서 하늘을 나는 것은 서투르지만 대신 발달한 다리로 빠르게 달릴 수 있다.', 'Its short wings make flying difficult. Instead, this Pokémon runs at high speed on developed legs.'),
  ('national', 85, 85, true, '두두의 머리 중 한 쪽이 분열한 변종. 초원을 시속 60km로 달린다.', 'One of Doduo’s two heads splits to form a unique species. It runs close to 40 mph in prairies.'),
  ('national', 86, 86, true, '얼어붙을 정도로 추운 곳을 좋아한다. 영하 10도 정도의 물속에서 기분 좋게 헤엄친다.', 'Loves freezing-cold conditions. Relishes swimming in a frigid climate of around 14 degrees Fahrenheit.'),
  ('national', 87, 87, true, '온몸이 눈처럼 새하얗다. 추위에 강해 얼음이 떠 있는 바다도 기운차게 헤엄쳐 다닌다.', 'Its entire body is a snowy white. Unharmed by even intense cold, it swims powerfully in icy waters.'),
  ('national', 88, 88, true, '진흙이 뭉쳐져서 태어났다. 악취 때문에 건드릴 엄두가 안 나고 지나간 자리에는 풀 한 포기 나지 않는다.', 'Made of congealed sludge. It smells too putrid to touch. Even weeds won’t grow in its path.'),
  ('national', 89, 89, true, '악취가 심하다! 기절할 정도로 강렬하지만 질뻐기는 코가 퇴화해서 냄새를 맡지 못한다.', 'Smells so awful, it can cause fainting. Through degeneration of its nose, it lost its sense of smell.'),
  ('national', 90, 90, true, '단단한 껍데기는 어떤 공격도 튕겨낸다. 껍데기를 열었을 때 안쪽을 공격당하는 것에는 약하다.', 'Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.'),
  ('national', 91, 91, true, '한번 껍질을 닫아버리면 어떤 괴력의 소유자도 여는 것은 불가능하다.', 'Once it slams its shell shut, it is impossible to open, even by those with superior strength.'),
  ('national', 92, 92, true, '몸은 옅은 가스로 되어 있어 어디든지 숨어들어 가지만 바람이 불면 날아가 버린다.', 'Gaseous and completely impalpable. Also highly dangerous— inhaling part of its poisonous body will cause one to faint instantly.'),
  ('national', 93, 93, true, '어둠 속에서 아무도 없는데도 누군가가 보고 있다는 느낌이 들면 그곳에 고우스트가 있는 것이다.', 'This frightful, malevolent spirit can glide through walls, appearing wherever it likes. According to rumor, victims of a Haunter''s lick will wither to death day by day.'),
  ('national', 94, 94, true, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'Possesses potential victims'' shadows in an effort to steal away the victims'' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!'),
  ('national', 95, 95, true, '크고 튼튼한 몸을 뒤틀고 꼬아서 시속 80km로 힘차게 땅을 파나간다.', 'This chain of immense stones resembles a giant serpent. Tremors shake the earth above as it burrows deep beneath the ground, feeding on boulders as it goes.'),
  ('national', 96, 96, true, '언제나 함께 잠들다 보면 가끔 옛날에 먹었던 꿈을 보여줄 때가 있다.', 'If you sleep by it all the time, it will sometimes show you dreams it had eaten in the past.'),
  ('national', 97, 97, true, '우연히 마주쳤을 때 다른 곳으로 눈을 돌리지 않으면 위험하다. 손에 든 추로 잠재워 버린다.', 'Avoid eye contact if you come across one. It will try to put you to sleep by using its pendulum.'),
  ('national', 98, 98, true, '위험이 닥치면 입에서 뿜어내는 거품으로 전신을 감싸서 몸을 크게 보이려고 한다.', 'If it senses danger approaching, it cloaks itself with bubbles from its mouth so it will look bigger.'),
  ('national', 99, 99, true, '큰 집게는 뛰어난 파괴력을 지녔지만 너무 무거워서 싸우지 않을 때는 거추장스럽다.', 'Its oversized claw is very powerful, but when it’s not in battle, the claw just gets in the way.'),
  ('national', 100, 100, true, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.'),
  ('national', 101, 101, true, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.'),
  ('national', 102, 102, true, '6마리가 아니면 진정하지 못한다. 1마리라도 없어지면 바로 도망태세가 된다.', 'These Pokémon get nervous when they’re not in a group of six. The minute even one member of the group goes missing, Exeggcute become cowardly.'),
  ('national', 103, 103, true, '3개의 머리가 똘똘 뭉쳐서 쏘는 사이코 파워는 강력하다. 날씨가 흐리면 움직임이 둔하다.', 'When they work together, Exeggutor’s three heads can put out powerful psychic energy. Cloudy days make this Pokémon sluggish.'),
  ('national', 104, 104, true, '죽은 어미의 뼈를 머리에 쓰고 있다. 어미의 꿈을 꾸고 울기도 하지만 눈물을 흘릴 때마다 강해진다.', 'This Pokémon wears the skull of its deceased mother. Sometimes Cubone’s dreams make it cry, but each tear Cubone sheds makes it stronger.'),
  ('national', 105, 105, true, '진화로 인해 쓰고 있던 어미의 뼈는 일체화되었고 성격은 더욱 난폭해졌다.', 'When this Pokémon evolved, the skull of its mother fused to it. Marowak’s temperament also turned vicious at the same time.'),
  ('national', 106, 106, true, '다리를 자유자재로 늘이고 줄인다. 상대가 멀리 떨어져 있어도 다리를 늘여서 차올릴 수 있다.', 'The legs freely contract and stretch. The stretchy legs allow it to hit a distant foe with a rising kick.'),
  ('national', 107, 107, true, '공기마저 베어 가르는 펀치. 하지만 3분간 공격하면 잠시 쉬고 싶어하는 것 같다.', 'Its punches slice the air. However, it seems to need a short break after fighting for three minutes.'),
  ('national', 108, 108, true, '벌레포켓몬이 주된 먹이다. 긴 혀로 상대를 핥아 마비시킨 후 통째로 삼킨다.', 'Wields its long tongue deftly, as though it were an arm. The Pokémon''s viscous saliva, once it has been collected and boiled down, yields a strong and highly useful adhesive.'),
  ('national', 109, 109, true, '오염된 공기를 좋아한다. 옛날 가라르지방에는 지금보다 많은 또가스가 있었다고 한다.', 'It adores polluted air. Some claim that Koffing used to be more plentiful in the Galar region than they are now.'),
  ('national', 110, 110, true, '가라르의 또도가스보다 공기를 흡입하는 힘은 조금 약하지만 내뿜는 독소는 강력하다.', 'It can’t suck in air quite as well as a Galarian Weezing, but the toxins it creates are more potent than those of its counterpart.'),
  ('national', 111, 111, true, '한 가지만 기억할 수 있다. 돌진하기 시작하면 이유가 무엇이었든 금방 잊어버린다.', 'Ludicrously strong—when it butts heads with a mountain, it is the mountain that shatters. But its short legs struggle with turns, and it is incapable of stopping unless it collides with something.'),
  ('national', 112, 112, true, '전신을 갑옷 같은 피부로 보호하고 있다. 2000도의 마그마 속에서도 살 수 있다.', 'Rapidly rotates its horn to bore through bedrock. It swaggers around volcanic regions, protected from the lava''s heat by its tough, armorlike hide.'),
  ('national', 113, 113, true, '원래 움직임이 둔했지만 알을 노리는 자들로부터 지켜내기 위해 도주 속도가 빨라졌다.', 'This purehearted Pokémon shares its eggs with the injured.'),
  ('national', 114, 114, true, '덩굴은 독특한 향이 난다. 가라르 일부 지역에서는 허브로 사용되고 있다.', 'It is cloaked entirely in blue vines, preventing any glimpse of its true identity. The vines impart a refreshing sensation when chewed—they''re useful as a spice.'),
  ('national', 115, 115, true, '새끼가 없는 캥카가 조난한 사람의 아이를 길렀다는 기록이 있다.', 'There are records of a lost human child being raised by a childless Kangaskhan.'),
  ('national', 116, 116, true, '물속에서 춤추듯이 헤엄쳐 소용돌이를 만든다. 동료와 소용돌이의 크기를 겨루며 논다.', 'They swim with dance-like motions and cause whirlpools to form. Horsea compete to see which of them can generate the biggest whirlpool.'),
  ('national', 117, 117, true, '입은 가늘지만 흡인력은 강하다. 입보다 큰 먹이도 순식간에 빨아들여 먹는다.', 'Seadra’s mouth is slender, but its suction power is strong. In an instant, Seadra can suck in food that’s larger than the opening of its mouth.'),
  ('national', 118, 118, true, '등지느러미와 가슴지느러미가 근육처럼 발달하여 물속을 5노트의 속도로 헤엄친다.', 'Its dorsal and pectoral fins are strongly developed like muscles. It can swim at a speed of five knots.'),
  ('national', 119, 119, true, '뿔로 강바닥의 바위를 파헤쳐 둥지를 만드는 이유는 낳은 알이 떠내려가지 않도록 하기 위함이다.', 'Using its horn, it bores holes in riverbed boulders, making nests to prevent its eggs from washing away.'),
  ('national', 120, 120, true, '물고기포켓몬에게 물리곤 하지만 몸이 찢겨도 금방 재생되기 때문에 신경 쓰지 않는다.', 'Fish Pokémon nibble at it, but Staryu isn’t bothered. Its body regenerates quickly, even if part of it is completely torn off.'),
  ('national', 121, 121, true, '몸을 고속으로 회전시켜 바다를 헤엄치며 작은 플랑크톤을 흡수한다.', 'Starmie swims by spinning its body at high speed. As this Pokémon cruises through the ocean, it absorbs tiny plankton.'),
  ('national', 122, 122, true, '팬터마임이 특기다. 손가락에서 내보내는 파동으로 벽을 만들어 갖은 공격으로부터 몸을 지킨다.', 'The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.'),
  ('national', 123, 123, true, '숲속에서 많은 나무가 베인 채 쓰러져 있는 장소를 발견했다면 그곳은 스라크의 영역이다.', 'The large, wickedly sharp scythes on its forearms are truly fearsome weapons. Prey''s attempts to flee are unfailingly thwarted by this Pokémon''s nimble motions.'),
  ('national', 124, 124, true, '가라르에는 아름답고 섬세한 울음소리를 가진 루주라가 많아서 팬도 있을 정도다.', 'The Jynx of Galar often have beautiful and delicate voices. Some of these Pokémon have even gathered a fan base.'),
  ('national', 125, 125, true, '폭풍이 치면 높은 나무 주위에 모여 번개가 떨어지기를 가만히 기다린다.', 'Feeds on electrical energy. During sudden showers beneath looming thunderclouds, one can observe Electabuzz scaling tall trees, where the Pokémon will then wait for lightning to strike.'),
  ('national', 126, 126, true, '온몸이 늘 불타고 있다. 화재를 일으키는 원인 중 하나로 두려움의 대상이 되고 있다.', 'Legend has it that this Pokémon was born from the crater of a volcano. When wounded, it bathes in lava to heal its body, much as one would soak in a hot spring.'),
  ('national', 127, 127, true, '뿔로 먹이를 찔러 넣어 그대로 두 동강으로 만들거나 강제로 던져버린다.', 'This Pokémon clamps its pincers down on its prey and then either splits the prey in half or flings it away.'),
  ('national', 128, 128, true, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'The Tauros of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.'),
  ('national', 129, 129, true, '유속이 빠른 곳에서는 그저 떠내려갈 뿐인 약하고 한심한 포켓몬이다.', 'A feeble, pitiful imbecile of a Pokémon that is nonetheless very hardy. Unperturbed by turbid water, it can be found living in all sorts of places.'),
  ('national', 130, 130, true, '한번 난동부리기 시작한 갸라도스는 태풍이 사납게 휘몰아쳐도 모든 것을 다 태워버린다.', 'I suspect this Pokémon to be the true identity of a dragon written of in ancient texts, which claimed that it razed an entire village with white-hot beams from its maw.'),
  ('national', 131, 131, true, '추위에 강해서 얼음 바다에서도 끄떡없다. 피부는 매끈매끈하고 조금 차갑다.', 'Crossing icy seas is no issue for this cold-resistant Pokémon. Its smooth skin is a little cool to the touch.'),
  ('national', 132, 132, true, '메타몽끼리 만나게 되면 상대와 똑같은 모습이 되기 위해 평소보다 격렬하게 움직인다.', 'When it encounters another Ditto, it will move faster than normal to duplicate that opponent exactly.'),
  ('national', 133, 133, true, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'Harbors the potential to evolve into manifold forms. Within Eevee lies the key to the mysteries of Pokémon evolution—I''m certain of it.'),
  ('national', 134, 134, true, '몸의 세포 구조가 물 분자와 닮았다. 물에 녹으면 보이지 않는다.', 'Tests show that its cells closely resemble water molecules, which perhaps explains its ability to conceal its form while submerged. I believe the origins of mermaid folklore lie with this Pokémon.'),
  ('national', 135, 135, true, '공기 중의 마이너스 이온을 빨아들여 약 10000볼트의 전기를 내뱉을 수 있다.', 'Bristles its fur into sharp, needlelike points when enraged. One can hear electricity crackle in its breath when it exhales.'),
  ('national', 136, 136, true, '들이마신 공기 중 일부는 체내의 불꽃 주머니로 보내져 1700도의 불꽃이 된다.', 'Flames burn within a saclike organ inside this Pokémon. When Flareon inhales, these flames grow in intensity, reaching a mighty 3,000 degrees Fahrenheit.'),
  ('national', 137, 137, true, '근래에는 컴퓨터 공간에서 대활약한다. 수상한 데이터가 없는지 체크하며 돌아다닌다.', 'It has no discernible heartbeat and does not seem to draw breath, and yet it appears to function without issue. I cannot even begin to explain this utterly bizarre anomaly.'),
  ('national', 138, 138, true, '멸종한 고대의 포켓몬이다. 10개의 다리로 물을 가르며 떠다니듯 헤엄친다.', 'This Pokémon is a member of an ancient, extinct species. Omanyte paddles through water with its 10 tentacles, looking like it’s just drifting along.'),
  ('national', 139, 139, true, '날카로운 이빨은 바위도 부수지만 촉수가 닿는 범위 안의 먹이만 공격할 수 있다.', 'Omastar’s sharp fangs could crush rock, but the Pokémon can attack only the prey that come within reach of its tentacles.'),
  ('national', 140, 140, true, '멸종되었다는 이야기가 있지만 일부 지역에서는 제법 많이 목격되는 듯하다.', 'While some say this species has gone extinct, Kabuto sightings are apparently fairly common in some places.'),
  ('national', 141, 141, true, '멸종한 이유는 불명확하다. 따듯한 바다에 살고 있던 난폭한 고대의 포켓몬이다.', 'The cause behind the extinction of this species is unknown. Kabutops were aggressive Pokémon that inhabited warm seas.'),
  ('national', 142, 142, true, '톱 같은 이빨은 강철포켓몬의 피부도 갈기갈기 베어 가른다.', 'Aerodactyl’s sawlike fangs can shred skin to tatters—even the skin of Steel-type Pokémon.'),
  ('national', 143, 143, true, '위장이 튼튼해서 곰팡이가 피거나 썩은 것을 먹어도 배탈이 나지 않는다.', 'This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.'),
  ('national', 144, 144, true, '얼음을 자유자재로 조종하는 힘을 가졌다. 영구 동토의 설산에 살고 있다고 한다.', 'This Pokémon can control ice at will. Articuno is said to live in snowy mountains riddled with permafrost.'),
  ('national', 145, 145, true, '날개를 비비대면 바로 천둥이 친다고 전해지는 전설의 새포켓몬이다.', 'Zapdos is a legendary bird Pokémon. It’s said that when Zapdos rubs its feathers together, lightning will fall immediately after.'),
  ('national', 146, 146, true, '아름답게 타오르는 날개로 산길을 비춰 조난자를 도왔다고 전해져 오고 있다.', 'There are stories of this Pokémon using its radiant, flame-cloaked wings to light up paths for those lost in the mountains.'),
  ('national', 147, 147, true, '오랫동안 환상이라고 불렸다. 이마에 있는 작은 돌기는 성장하고 있는 뿔이다.', 'This Pokémon was long considered to be no more than a myth. The small lump on a Dratini’s forehead is actually a horn that’s still coming in.'),
  ('national', 148, 148, true, '꼬리의 구슬에 힘을 모아 날씨를 조종한다. 오라에 둘러싸인 모습은 신비롭다.', 'This Pokémon gathers power in the orbs on its tail and controls the weather. When enshrouded by an aura, Dragonair has a mystical appearance.'),
  ('national', 149, 149, true, '바다의 화신이라고 불린다. 망나뇽 형태의 조각상을 뱃머리에 두는 배도 많다.', 'This Pokémon is known as the Sea Incarnate. Figureheads that resemble Dragonite decorate the bows of many ships.'),
  ('national', 150, 150, true, '뮤의 유전자와 거의 같다. 하지만 크기도 성격도 무서울 정도로 다르다.', 'Its DNA is almost the same as Mew’s. However, its size and disposition are vastly different.'),
  ('national', 151, 151, true, '현미경으로 관찰하면 매우 짧고 가는 털이 촘촘하게 나 있다.', 'When viewed through a microscope, this Pokémon’s short, fine, delicate hair can be seen.'),
  ('national', 152, 152, true, '잎사귀를 휘둘러 상대를 위협하지만 잎사귀에서 달콤한 향기가 풍겨 나와 서로 온화한 분위기가 된다.', 'In battle, Chikorita waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling Pokémon and creating a cozy, friendly atmosphere all around.'),
  ('national', 153, 153, true, '목 주변의 둥그렇게 말린 잎사귀 안에는 작은 새싹 한 개가 나 있다. 그 향기는 사람을 기운 나게 한다.', 'Bayleef’s neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy.'),
  ('national', 154, 154, true, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit.'),
  ('national', 155, 155, true, '등에서 불꽃을 내뿜어 몸을 지킨다. 화났을 때의 불꽃은 기운차지만 지쳤을 때는 불완전연소한다.', 'Hails from the Johto region. Though usually curled into a ball due to its timid disposition, it harbors tremendous firepower.'),
  ('national', 156, 156, true, '불꽃의 기세와 열풍으로 위협한다. 재빠른 몸동작으로 상대의 공격을 피하면서 동시에 불꽃으로 태운다.', 'This creature''s fur is most mysterious—it is wholly impervious to the burning touch of flame. Should Quilava turn its back to you, take heed! Such a posture indicates a forthcoming attack.'),
  ('national', 157, 157, true, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
  ('national', 158, 158, true, '몸은 작지만 턱의 힘은 강하다. 리아코 나름은 살포시 물려고 하지만 큰 상처를 입힐 정도의 힘이 있다.', 'Despite the smallness of its body, Totodile’s jaws are very powerful. While the Pokémon may think it is just playfully nipping, its bite has enough power to cause serious injury.'),
  ('national', 159, 159, true, '한 번 물고 늘어지면 절대로 놓지 않는다. 이빨 끝이 낚싯바늘처럼 휘어져 있어서 한 번 들어가면 빠지지 않는다.', 'Once Croconaw has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in.'),
  ('national', 160, 160, true, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.'),
  ('national', 161, 161, true, '잠잘 때는 교대로 망을 본다. 위험을 탐지하면 동료를 깨운다. 무리에서 떨어지면 무서워서 자지 못한다.', 'When Sentret sleeps, it does so while another stands guard. The sentry wakes the others at the first sign of danger. When this Pokémon becomes separated from its pack, it becomes incapable of sleep due to fear.'),
  ('national', 162, 162, true, '적에게 습격당해도 좁은 틈으로 쑥 들어가서 도망갈 수 있다. 팔다리는 짧지만 매우 날쌔다.', 'Furret has a very slim build. When under attack, it can slickly squirm through narrow spaces and get away. In spite of its short limbs, this Pokémon is very nimble and fleet.'),
  ('national', 163, 163, true, '언제나 정해진 시간이 되면 울음소리를 내어 시계 대용으로 데리고 다니는 트레이너도 있다.', 'It begins to hoot at the same time every day. Some Trainers use them in place of clocks.'),
  ('national', 164, 164, true, '무언가를 생각하기 시작하면 목을 180도 회전시켜 두뇌 회전을 높인다.', 'When it needs to think, it rotates its head 180 degrees to sharpen its intellectual power.'),
  ('national', 165, 165, true, '매우 겁이 많은 포켓몬이다. 동료와 함께 리플렉터를 펼쳐서 보금자리를 지키고 있다.', 'These very cowardly Pokémon join together and use Reflect to protect their nest.'),
  ('national', 166, 166, true, '반짝이는 가루를 흩뿌리며 밤하늘을 난다. 가루가 몸에 붙으면 좋은 일이 생긴다고 전해진다.', 'It flies through the night sky, sprinkling sparkly dust. According to some, if that dust sticks to you, good things will happen to you.'),
  ('national', 167, 167, true, '이빨의 독은 그다지 강하진 않지만 둥지에 걸려서 움직일 수 없는 먹이를 약하게 만들기에는 충분하다.', 'Although the poison from its fangs isn’t that strong, it’s potent enough to weaken prey that gets caught in its web.'),
  ('national', 168, 168, true, '실을 뿜어서 먹이를 잡는다. 밤이 되면 둥지를 떠나 적극적으로 사냥에 나선다.', 'It spews threads from its mouth to catch its prey. When night falls, it leaves its web to go hunt aggressively.'),
  ('national', 169, 169, true, '4장의 날개를 자유자재로 움직이며 날갯짓한다. 좁은 동굴에서도 속도를 늦추지 않고 날아다닐 수 있다.', 'Its hind limbs have become another set of wings. Crobat expertly maneuvers its four wings to dart in exquisite fashion through even the most confined caves without losing any speed.'),
  ('national', 170, 170, true, '어두운 해저에서는 항상 깜빡거리는 촉수의 빛이 유일한 통신 수단이다.', 'On the dark ocean floor, its only means of communication is its constantly flashing lights.'),
  ('national', 171, 171, true, '강한 빛을 발산해 먹이의 눈을 멀게 한다. 허점을 보이면 전격을 먹인다.', 'This Pokémon flashes a bright light that blinds its prey. This creates an opening for it to deliver an electrical attack.'),
  ('national', 172, 172, true, '볼의 전기 주머니가 작아서 조금이라도 전기가 넘치게 되면 자기 자신이 감전되어 버린다.', 'Pichu stores electricity in the sacs on its cheeks but discharges it inadvertently when agitated or excited. Being yet immature, the Pokémon''s handling of electricity is rather inept.'),
  ('national', 173, 173, true, '실루엣이 별 모양이다. 그 때문에 별똥별을 타고 온다고 여겨진다.', 'In silhouette, they resemble twinkling starlight. When shooting stars rain from the night sky, Cleffa gather in numbers and dance as though they are indeed incarnations of the stars.'),
  ('national', 174, 174, true, '부드러운 몸으로 통통 튀며 움직인다. 체온이 오르면 몸은 짙은 핑크색이 된다.', 'Taking advantage of the softness of its body, Igglybuff moves as if bouncing. Its body turns a deep pink when its temperature rises.'),
  ('national', 175, 175, true, '행운의 상징이다. 껍질 안에는 행복이 가득 담겨 있다고 한다.', 'This ovate creature is frequently mistaken for a moving egg when encountered out in the fields or in the mountains. Its guileless smile soothes the soul.'),
  ('national', 176, 176, true, '상냥한 사람 곁에 있지 않으면 기운을 내지 못한다. 날개를 움직이지 않고도 공중에 뜰 수 있다.', 'No records exist of Togetic being seen in the wilds. Rumors abound that it evolves under the loving care of a trusted human companion, upon whom the Pokémon then bestows great joy.'),
  ('national', 177, 177, true, '날개가 아직 잘 발달하지 못해서 점프하듯 이동한다. 항상 뭔가를 바라보고 있다.', 'Because its wings aren’t yet fully grown, it has to hop to get around. It is always staring at something.'),
  ('national', 178, 178, true, '과거와 미래를 내다볼 수 있다. 매일 태양의 움직임을 관찰하는 이상한 포켓몬이다.', 'This odd Pokémon can see both the past and the future. It eyes the sun’s movement all day.'),
  ('national', 179, 179, true, '솜털이 마찰하여 전기가 모인다. 귀엽다고 맨손으로 만지면 따끔하게 저리고 아프다.', 'Rubbing its fleece generates electricity. You’ll want to pet it because it’s cute, but if you use your bare hand, you’ll get a painful shock.'),
  ('national', 180, 180, true, '푹신푹신한 털에 전기를 저장한다. 너무 많이 저장해서 여기저기 반질반질하게 털이 빠져 버렸다.', 'It stores electricity in its fluffy fleece. If it stores up too much, it will start to go bald in those patches.'),
  ('national', 181, 181, true, '꼬리는 강하고 밝게 빛난다. 뱃사람들의 길잡이로서 옛날부터 소중히 여겨져 왔다.', 'Its tail shines bright and strong. It has been prized since long ago as a beacon for sailors.'),
  ('national', 182, 182, true, '가끔 아르코가 모여서 춤을 추는 듯한 동작을 한다. 태양을 부르는 의식이라 전해진다.', 'Bellossom gather at times and appear to dance. They say that the dance is a ritual to summon the sun.'),
  ('national', 183, 183, true, '물을 잘 튕겨내는 털은 차가운 바다에 있다가 나와도 금방 말라서 춥지 않다.', 'Even after Marill swims in a cold sea, its water- repellent fur dries almost as soon as Marill leaves the water. That’s why this Pokémon is never cold.'),
  ('national', 184, 184, true, '공기로 가득 찬 거품을 만든다. 루리리가 강에서 놀 때는 이 거품으로 감싸준다.', 'These Pokémon create air-filled bubbles. When Azurill play in rivers, Azumarill will cover them with these bubbles.'),
  ('national', 185, 185, true, '습격당하지 않도록 나무 흉내를 낸다. 물에 약하기 때문에 비가 내리면 어느 틈에 모습을 감춰버린다.', 'Though it pretends to be a tree, it fails to fool even children. To the touch, its body feels more like rock than tree bark. Sudowoodo''s extreme aversion to water merits special note.'),
  ('national', 186, 186, true, '수컷의 울음소리가 더 크다. 나지막하고 위협적인 목소리로 우는 왕구리가 암컷에게 인기다.', 'The cry of a male is louder than that of a female. Male Politoed with deep, menacing voices find more popularity with the opposite gender.'),
  ('national', 187, 187, true, '바람을 타고 둥둥 떠다니는 포켓몬이다. 강풍의 기척을 느끼면 동료끼리 잎사귀를 휘감아 날아가지 않도록 준비한다.', 'This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, Hoppip links its leaves with other Hoppip to prepare against being blown away.'),
  ('national', 188, 188, true, '기온이 18도를 넘으면 꽃이 핀다. 온도에 따라 꽃이 피는 모습이 바뀌어서 온도계 대신 쓰기도 한다.', 'Skiploom’s flower blossoms when the temperature rises above 64 degrees Fahrenheit. How much the flower opens depends on the temperature. For that reason, this Pokémon is sometimes used as a thermometer.'),
  ('national', 189, 189, true, '따뜻한 남풍을 타고 바다를 건너 외국까지 날아가는 포켓몬이다. 차가운 공기에 닿으면 땅에 내려온다.', 'Jumpluff rides warm southern winds to cross the sea and fly to foreign lands. The Pokémon descends to the ground when it encounters cold air while it is floating.'),
  ('national', 190, 190, true, '나무 위에서 먹이를 찾는다. 좋아하는 달콤아를 발견하면 흥분해서 덤벼든다.', 'This treetop dweller possesses a tail as dexterous as a hand. Ancient writings describe this Pokémon as a one-armed oddity.'),
  ('national', 191, 191, true, '몸에 모은 영양을 진화할 때까지 간직하기 위해 거의 움직이려 하지 않는다. 아무것도 먹지 않고 아침 이슬만 마시고 있다.', 'Sunkern tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew.'),
  ('national', 192, 192, true, '태양 에너지에서 영양을 만들어낸다. 기온이 높은 낮에는 활발하게 움직이고 태양이 지면 뚝 하니 움직이지 않게 된다.', 'Sunflora converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night.'),
  ('national', 193, 193, true, '눈알을 움직이지 않고 360도를 볼 수 있다. 급브레이크나 방향 전환이 특기다. 노린 먹이를 빠르게 몰아넣는다.', 'Its frail wings are so thin that one can see clear through them. However, during flight these wings exhibit the power to churn air with force enough to launch a house skyward.'),
  ('national', 194, 194, true, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'When walking on land, it covers its body with a poisonous film that keeps its skin from dehydrating.'),
  ('national', 195, 195, true, '몸은 항상 미끄럽다. 헤엄칠 때마다 강바닥에 머리를 부딪치지만 신경 쓰지 않는다.', 'Its body is always slimy. It often bangs its head on the river bottom as it swims but seems not to care.'),
  ('national', 196, 196, true, '이마의 구슬에서 사이코 파워를 방사해서 싸운다. 파워가 다하면 구슬의 색이 흐려진다.', 'Wields an arcane power with which it can predict the weather and even people''s thoughts. When bathed in sunshine, the scarlet orb on its brow glows and builds energy.'),
  ('national', 197, 197, true, '보름달이 뜬 밤이나 흥분했을 때 전신의 고리 무늬가 노랗게 빛난다.', 'It is most active in the wee hours of the night, when moonlight bathes the land. Its large eyes can pierce the darkness and perceive prey with absolute clarity.'),
  ('national', 198, 198, true, '보스를 위해 반짝반짝 빛나는 것을 찾고 있다. 불길한 존재로 여겨 몹시 싫어하는 사람도 많다.', 'Widely shunned as a bearer of ill fortune. Upon crossing paths with this creature, I''ve been told one must chant ”Workrum, Workrum—bad luck, don''t come” as a protective incantation.'),
  ('national', 199, 199, true, '아무리 어려운 문제를 물어봐도 모두 해결해주지만 그 누구도 야도킹의 말을 이해하지 못한다.', 'Slowking can solve any problem presented to it, but no one can understand a thing Slowking says.'),
  ('national', 200, 200, true, '사람이 울부짖는 소리를 흉내 내 모두를 겁주고 기뻐한다. 담력이 강한 상대는 좋아하지 않는다.', 'It conceals itself in darkness, sending chills up travelers'' spines with its childlike weeping. As it observes the frightened travelers with glee, the red orbs upon its chest let off an eerie light.'),
  ('national', 201, 201, true, '고대 문자를 닮은 모습의 포켓몬이다. 먼저 생겨난 것은 문자인가 안농인가. 연구 중이지만 아직도 수수께끼다.', 'It is hard to believe these strangely shaped Pokémon are truly living creatures. I''ve pointed out that the species'' many forms resemble writing from other lands; no one will take me seriously.'),
  ('national', 202, 202, true, '새까만 꼬리를 숨기기 위해 어둠 속에서 은밀히 지내고 있다. 자신이 먼저 공격하는 일은 없다.', 'To keep its pitch-black tail hidden, it lives quietly in the darkness. It is never first to attack.'),
  ('national', 203, 203, true, '꼬리의 뇌는 생각을 할 수 없을 정도로 작지만 자지 않아도 괜찮아서 24시간 주변을 계속 망보고 있다.', 'Girafarig’s rear head contains a tiny brain that is too small for thinking. However, the rear head doesn’t need to sleep, so it can keep watch over its surroundings 24 hours a day.'),
  ('national', 204, 204, true, '나무껍질을 타액으로 붙여서 몸을 두껍고 크게 만든다. 나이를 먹은 피콘은 엄청나게 크다.', 'It sticks tree bark to itself with its saliva, making itself thicker and larger. Elderly Pineco are ridiculously huge.'),
  ('national', 205, 205, true, '먹이를 삼키는 순간에는 껍질 안의 모습이 나타나지만 그 모습을 본 자는 아직 없다.', 'In the moment that it gulps down its prey, the inside of its shell is exposed, but to this day, no one has ever seen that sight.'),
  ('national', 206, 206, true, '미로 같은 굴에 산다. 흙냄새로 자신이 있는 곳을 알 수 있어 절대 길을 잃지 않는다.', 'The nests Dunsparce live in are mazes of tunnels. They never get lost in their own nests—they can tell where they are by the scent of the dirt.'),
  ('national', 207, 207, true, '소리 내지 않고 미끄러지듯 활공한다. 양손의 커다란 손톱과 발의 발톱으로 먹이의 얼굴에 달라붙어 독침을 찌른다.', 'Its tail is tipped by a thick, horrible stinger. To bring down prey, it will first obscure their vision by covering their faces with its body, and then it will use the stinger to inject them with venom.'),
  ('national', 208, 208, true, '흙과 함께 삼킨 강철이 축적되어 몸이 변화한 것이라 여겨지고 있다.', 'This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.'),
  ('national', 209, 209, true, '겉보기와 다르게 겁쟁이라 다른 강아지포켓몬과 함께 있으면 괴롭힘을 당할 때도 있다.', 'In contrast to its appearance, it’s quite timid. When playing with other puppy Pokémon, it sometimes gets bullied.'),
  ('national', 210, 210, true, '젊은 여성에게 인기가 많지만 겁쟁이인데다가 섬세하기 때문에 지킴이로는 무능하다.', 'Although it’s popular with young people, Granbull is timid and sensitive, so it’s totally incompetent as a watchdog.'),
  ('national', 211, 211, true, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
  ('national', 212, 212, true, '몸은 가늘지만 공격력은 무시무시하다. 몸의 근육도 금속으로 되어 있다.', 'Evolved by way of a curious item. The shell covering its body has been shown to be stronger than forged steel.'),
  ('national', 213, 213, true, '항아리 같은 등껍질 속에 모은 나무열매는 어느샌가 걸쭉한 주스로 변한다.', 'The berries stored in its vaselike shell eventually become a thick, pulpy juice.'),
  ('national', 214, 214, true, '자신 몸무게의 100배에 달하는 무게도 거뜬히 들어 올리는 괴력을 자랑하는 포켓몬이다.', 'This Pokémon has an unparalleled horn. Heracross itself demonstrates tremendous power—it''s capable of throwing several people trained in the traditional arts of war at once.'),
  ('national', 215, 215, true, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.'),
  ('national', 216, 216, true, '꿀이 밴 손바닥을 핥고 있다. 깜지곰의 꿀은 과일과 독침붕이 모은 꽃가루가 혼합되어 만들어진다.', 'It licks its paws because of the sweet honey that has soaked into them. It is cunning, stealing into the nests of Combee and taking for itself the honey that the Combee have amassed.'),
  ('national', 217, 217, true, '숲 속에는 링곰이 먹이를 수집하는 큰 나무나 시냇가가 여기저기에 있다고 한다. 매일 먹이를 모으며 숲을 걷는다.', 'When the cold season arrives in Hisui, this Pokémon will wander fields and mountains alike in search of its favorite berries. Ursaring''s hunger during this time makes it a ferocious danger.'),
  ('national', 218, 218, true, '몸 안에는 혈액 대신 필요한 영양과 산소를 운반하기 위해 작열하는 마그마가 순환되고 있다.', 'Slugma does not have any blood in its body. Instead, intensely hot magma circulates throughout this Pokémon’s body, carrying essential nutrients and oxygen to its organs.'),
  ('national', 219, 219, true, '체온이 약 1만 도나 돼서 빗방울이 몸에 닿으면 수증기가 자욱하게 피어나 주변이 깊은 안개에 둘러싸인다고 한다.', 'Magcargo’s body temperature is approximately 18,000 degrees Fahrenheit. Water is vaporized on contact. If this Pokémon is caught in the rain, the raindrops instantly turn into steam, cloaking the area in a thick fog.'),
  ('national', 220, 220, true, '좋은 냄새를 맡으면 뒷일을 생각하지 않고 냄새 나는 방향으로 대시해버린다.', 'Swinub excels at sniffing out mushrooms buried beneath grass or snow. Since ancient times, the people of Hisui have often relied upon this skill.'),
  ('national', 221, 221, true, '4개의 다리는 짧지만 발굽이 넓고 거칠거칠하므로 눈 위도 미끄러지지 않고 걸을 수 있다.', 'The long fur of this Pokémon covers its eyes, ears, and even limbs, allowing Piloswine to resist harshly frigid conditions. The Pokémon''s white tusks can be used to defeat its enemies.'),
  ('national', 222, 222, true, '따뜻한 바다에 서식한다. 태고에는 가라르 근해에서도 많은 수가 서식했었다.', 'These Pokémon live in warm seas. In prehistoric times, many lived in the oceans around the Galar region as well.'),
  ('national', 223, 223, true, '빨판처럼 변화한 등지느러미로 만타인에게 달라붙어 먹다 남은 것을 얻어먹고 있다.', 'Spits water from its mouth with incredible accuracy. It captures Burmy by shooting them down off the branches from which they dangle.'),
  ('national', 224, 224, true, '머리가 돌처럼 단단하다. 빨판이 붙어 있는 다리를 휘감아 끊임없이 머리로 세게 때린다.', 'While Octillery still shoots water from its mouth, the drastic anatomical difference between it and Remoraid meant that for a long time, no one believed the former evolved from the latter.'),
  ('national', 225, 225, true, '자신의 먹이를 사람이나 포켓몬에게 나눠주는 습성이 있어 언제나 먹이를 찾아다닌다.', 'It has a generous habit of sharing its food with people and Pokémon, so it’s always scrounging around for more food.'),
  ('national', 226, 226, true, '여유롭게 바다를 헤엄친다. 먹다 남은 음식을 노린 총어가 달라붙어 있어도 신경 쓰지 않는다.', 'This calm and gentle Pokémon swims gracefully through the sea. After building speed, it can leap out of the water. It is often misidentified as a bird Pokémon due to this behavior.'),
  ('national', 227, 227, true, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'People fashion swords from Skarmory’s shed feathers, so this Pokémon is a popular element in heraldic designs.'),
  ('national', 228, 228, true, '동이 트기 전에 기분 나쁜 울음을 반복하여 자신들 무리의 존재를 어필한다.', 'They make repeated eerie howls before dawn to call attention to their pack.'),
  ('national', 229, 229, true, '기분 나쁜 울음소리가 특징이다. 옛날 사람들은 지옥에서 온 사자라고 여겨 두려워했다.', 'Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it.'),
  ('national', 230, 230, true, '떨어진 비늘은 왕족에게 헌상될 정도의 최상품으로 심오한 빛을 띤다.', 'Scales shed by this Pokémon have such a splendorous gleam to them that they’ve been given to royalty as gifts.'),
  ('national', 231, 231, true, '긴 코를 써서 물을 끼얹는다. 동료가 모여들면 서로 물을 끼얹는다. 흠뻑 젖은 몸을 물가에서 말린다.', 'Phanpy uses its long nose to shower itself. When others gather around, they thoroughly douse each other with water. These Pokémon can be seen drying their soaking-wet bodies at the edge of water.'),
  ('national', 232, 232, true, '단단한 몸으로 부딪치면 집도 부서진다. 그 힘을 이용해 산길을 막고 있는 토사를 치우는 일을 돕는다.', 'If Donphan were to tackle with its hard body, even a house could be destroyed. Using its massive strength, the Pokémon helps clear rock and mud slides that block mountain trails.'),
  ('national', 233, 233, true, 'AI 기능을 탑재한 결과 폴리곤2끼리만 통하는 수수께끼의 언어로 말하기 시작했다.', 'A bizarre item caused this Pokémon to evolve. While it now exhibits many new gestures and expressions, its biology remains inscrutable.'),
  ('national', 234, 234, true, '멋지게 생긴 뿔은 미술품으로 비싸게 팔리기 때문에 멸종 직전까지 남획됐었던 포켓몬이다.', 'Its strangely shaped antlers have the power to bewitch those who see them. Medicine made by grinding up the black orbs from fallen antlers is an effective treatment for insomnia.'),
  ('national', 235, 235, true, '꼬리 끝에서 나오는 체액으로 마크를 그린다. 마크에 따라서는 마니아에게 비싼 값에 거래된다.', 'It draws symbols with the fluid that oozes from the tip of its tail. Depending on the symbol, Smeargle fanatics will pay big money for them.'),
  ('national', 236, 236, true, '만만한 상대를 발견하면 바로 공격해오기 때문에 몸집이 작아도 방심은 할 수 없다.', 'Even though it is small, it can’t be ignored because it will slug any handy target without warning.'),
  ('national', 237, 237, true, '물구나무를 서서 상대의 타이밍을 흐트러뜨리고 그 틈에 화려한 발차기를 먹인다.', 'After doing a handstand to throw off the opponent’s timing, it presents its fancy kick moves.'),
  ('national', 238, 238, true, '호기심이 왕성한 포켓몬이다. 뭐든지 입술에 대보고 좋은지 싫은지 판단한다.', 'This is a very curious Pokémon. Smoochum decides what it likes and dislikes by touching things with its lips.'),
  ('national', 239, 239, true, '아직 전기를 모으는 게 서툴다. 전기를 먹기 위해 민가에 숨어들어 콘센트를 찾는다.', 'They generate electricity by spinning their arms. During a thunderstorm, if one hears the lively voices of children out in the wilderness, what one is actually hearing are the voices of Elekid.'),
  ('national', 240, 240, true, '화산 주위에 살고 있다. 하루를 마칠 때에는 마그마에 잠겨 피로를 푼다.', 'This Pokémon lives in volcanic areas. With each breath, sparks spurt from its mouth and nose. When Magby is in good health, its flames gain a yellow tint.'),
  ('national', 241, 241, true, '매일 우유를 짜지 않으면 컨디션이 나빠진다. 우유의 맛은 계절에 따라 다르다.', 'This Pokémon needs to be milked every day, or else it will fall ill. The flavor of Miltank milk changes with the seasons.'),
  ('national', 242, 242, true, '행복이 가득 찬 신비한 알을 낳는다. 먹은 사람은 누구에게나 친절해진다고 한다.', 'A kindhearted Pokémon that will care for any sick person or Pokémon until their health improves. The eggs it lays are delicious and bring good fortune to those who eat them.'),
  ('national', 243, 243, true, '번개의 스피드가 깃들어 있는 포켓몬이다. 그 울음소리는 번개가 내리쳤을 때처럼 공기를 떨리게 하며 대지를 흔든다.', 'Raikou embodies the speed of lightning. The roars of this Pokémon send shock waves shuddering through the air and shake the ground as if lightning bolts had come crashing down.'),
  ('national', 244, 244, true, '마그마의 정열이 깃들어 있는 포켓몬이다. 화산 분화 속에서 태어났다고 여겨지며 모든 것을 태워버리는 불꽃을 뿜어 올린다.', 'Entei embodies the passion of magma. This Pokémon is thought to have been born in the eruption of a volcano. It sends up massive bursts of fire that utterly consume all that they touch.'),
  ('national', 245, 245, true, '솟아나는 물의 부드러움이 깃들어 있는 포켓몬이다. 흐르는 듯한 몸놀림으로 대지를 달려 탁해진 물을 맑게 하는 힘을 지녔다.', 'Suicune embodies the compassion of a pure spring of water. It runs across the land with gracefulness. This Pokémon has the power to purify dirty water.'),
  ('national', 246, 246, true, '흙을 먹으며 살고 있다. 큰 산 하나를 다 먹으면 성장을 위해 잠자기 시작한다.', 'It feeds on soil. After it has eaten a large mountain, it will fall asleep so it can grow.'),
  ('national', 247, 247, true, '번데기지만 가만히 있지 않는다. 단단한 껍질 안에는 이미 팔다리가 만들어져 있다.', 'It will not stay still, even while it’s a pupa. It already has arms and legs under its solid shell.'),
  ('national', 248, 248, true, '지축을 울리면서 걸으면 큰 산조차 무너지며 주변의 지형은 변해버린다.', 'The quakes caused when it walks make even great mountains crumble and change the surrounding terrain.'),
  ('national', 249, 249, true, '가벼운 날갯짓만으로도 민가를 날려버릴 만한 파괴력을 지니고 있어서 해저에서 사람들 몰래 살게 됐다.', 'Lugia’s wings pack devastating power—a light fluttering of its wings can blow apart regular houses. As a result, this Pokémon chooses to live out of sight deep under the sea.'),
  ('national', 250, 250, true, '빛이 닿는 각도에 따라 일곱 빛깔로 반짝이는 깃털은 행복을 가져다준다고 한다. 무지개 끝에 산다고 전해진다.', 'Ho-Oh’s feathers glow in seven colors depending on the angle at which they are struck by light. These feathers are said to bring happiness to the bearers. This Pokémon is said to live at the foot of a rainbow.'),
  ('national', 251, 251, true, '미래에서 시간을 건너 찾아왔다. 상처를 치료하고 초목에 힘을 나누어준다.', 'This Pokémon traveled through time to come from the future. It bolsters grass and trees with its own strength, and it can heal wounds, too.'),
  ('kanto', 1, 1, true, '며칠 동안 아무것도 먹지 않아도 건강하다! 등에 있는 씨앗에는 많은 영양분이 있어서 문제없다!', 'It can go for days without eating a single morsel. In the bulb on its back, it stores energy.'),
  ('kanto', 2, 2, true, '양분을 흡수해서 커진 봉오리에서 향기가 나기 시작하면 곧 꽃이 핀다는 증거다.', 'The bud on its back grows by drawing energy. It gives off an aroma when it is ready to bloom.'),
  ('kanto', 3, 3, true, '등 위에 활짝 핀 큰 꽃은 태양 빛을 흡수해서 에너지로 변환할 수 있다.', 'The flower on its back catches the sun’s rays. The sunlight is then absorbed and used for energy.'),
  ('kanto', 4, 4, true, '조용한 곳에 데려가면 꼬리가 타고 있는 작은 소리가 들린다.', 'The flame at the tip of its tail makes a sound as it burns. You can only hear it in quiet places.'),
  ('kanto', 5, 5, true, '강한 적과 싸움을 거듭하다 흥분하면 푸르스름한 불꽃을 뿜어낼 때가 있다.', 'Tough fights could excite this Pokémon. When excited, it may breathe out bluish-white flames.'),
  ('kanto', 6, 6, true, '입에서 작렬하는 불꽃을 토해낼 때 꼬리의 끝이 더욱 붉고 격렬하게 타오른다.', 'When this Pokémon expels a blast of superhot fire, the red flame at the tip of its tail burns more intensely.'),
  ('kanto', 7, 7, true, '수면에서 물을 분사하여 먹이를 잡는다. 위험해지면 등껍질에 손발을 감추고 몸을 지킨다.', 'Shoots water at prey while in the water. Withdraws into its shell when in danger.'),
  ('kanto', 8, 8, true, '딱 하고 머리를 맞을 때 등껍질로 숨어서 피한다. 하지만 꼬리가 살짝 삐져나와 있다.', 'When tapped on its head, this Pokémon will pull it in, but its tail will still stick out a little bit.'),
  ('kanto', 9, 9, true, '상대를 겨냥한 다음 소방차의 호스보다 강한 기세로 물을 뿜는다.', 'Once it takes aim at its enemy, it blasts out water with even more force than a fire hose.'),
  ('kanto', 10, 10, true, '머리끝에 있는 더듬이를 건드리면 강렬한 냄새를 내서 몸을 보호하려 한다.', 'If you touch the feeler on top of its head, it will release a horrible stink to protect itself.'),
  ('kanto', 11, 11, true, '몸을 보호하기 위해 끊임없이 껍질을 단단하게 하지만 강한 충격을 받으면 내용물이 나와버린다.', 'Hardens its shell to protect itself. However, a large impact may cause it to pop out of its shell.'),
  ('kanto', 12, 12, true, '날개에 있는 맹독을 가진 인분에는 물을 튕겨내는 성질이 있어 비가 오는 날에도 날아다닐 수 있다.', 'Its wings, covered with poisonous powder, repel water. This allows it to fly in the rain.'),
  ('kanto', 13, 13, true, '머리에 날카로운 침을 지니고 있다. 우거진 숲이나 풀밭에 숨어 끊임없이 풀잎을 먹고 있다.', 'Beware of the sharp stinger on its head. It hides in grass and bushes where it eats leaves.'),
  ('kanto', 14, 14, true, '스스로는 거의 움직일 수 없지만 위험해지면 침을 세워서 독을 뿜을 때도 있는 듯하다.', 'Able to move only slightly. When endangered, it may stick out its stinger and poison its enemy.'),
  ('kanto', 15, 15, true, '양손과 엉덩이에 있는 3개의 독침으로 상대를 찌르고 찌르고 또 찌르며 공격한다.', 'It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.'),
  ('kanto', 16, 16, true, '얌전한 성격이라 습격당해도 반격하지 않고 모래를 뿌려서 몸을 지키는 경우가 많다.', 'Very docile. If attacked, it will often kick up sand to protect itself rather than fight back.'),
  ('kanto', 17, 17, true, '어마어마한 체력의 소유자로 넓은 영역을 날아다니며 먼 곳까지 먹이를 찾으러 간다.', 'This Pokémon is full of vitality. It constantly flies around its large territory in search of prey.'),
  ('kanto', 18, 18, true, '마하2의 속도로 비행하여 먹이를 찾는다. 그 커다란 발톱은 무기로서도 두려움의 대상이다.', 'This Pokémon flies at Mach 2 speed, seeking prey. Its large talons are feared as wicked weapons.'),
  ('kanto', 19, 19, true, '2개의 이빨로 뭐든지 일단 갉고 본다. 1마리를 발견했다면 그곳에 40마리는 살고 있을 것이다.', 'Will chew on anything with its fangs. If you see one, you can be certain that 40 more live in the area.'),
  ('kanto', 20, 20, true, '뒷다리에 달린 작은 물갈퀴로 강을 헤엄치는 이유는 물속에 있는 먹이를 잡기 위해서다.', 'Its hind feet are webbed. They act as flippers, so it can swim in rivers and hunt for prey.'),
  ('kanto', 21, 21, true, '높이 나는 것에 서투르다. 영역을 지키기 위해 맹렬한 스피드로 날아다닌다.', 'Inept at flying high. However, it can fly around very fast to protect its territory.'),
  ('kanto', 22, 22, true, '옛날부터 살고 있는 포켓몬. 조금이라도 위험을 감지하면 하늘 높이 날아가 버린다.', 'A Pokémon that dates back many years. If it senses danger, it flies high and away, instantly.'),
  ('kanto', 23, 23, true, '성장할수록 점점 길어진다. 밤에는 나뭇가지에 몸을 돌돌 말고 쉰다.', 'The older it gets, the longer it grows. At night, it wraps its long body around tree branches to rest.'),
  ('kanto', 24, 24, true, '무서워 보이는 배의 무늬는 연구 결과 6종류 정도의 패턴이 확인되었다.', 'The frightening patterns on its belly have been studied. Six variations have been confirmed.'),
  ('kanto', 25, 25, true, '숲에 사는 포켓몬. 볼에 있는 주머니에 전기를 모으고 있어 만지면 저릿저릿 저리다.', 'This forest-dwelling Pokémon stores electricity in its cheeks, so you’ll feel a tingly shock if you touch it.'),
  ('kanto', 26, 26, true, '몸에 전기가 모이면 공격적인 성격으로 변한다. 어두운 곳에서 빛나 보인다.', 'When electricity builds up inside its body, it becomes feisty. It also glows in the dark.'),
  ('kanto', 27, 27, true, '몸이 건조하다. 하지만 밤중에 기온이 내려가면 피부에 물방울이 맺힌다고 한다.', 'Its body is dry. When it gets cold at night, its hide is said to become coated with a fine dew.'),
  ('kanto', 28, 28, true, '발톱으로 할퀴는 것이 특기지만 싸우다가 부러질 때도 있다. 다음날이면 다시 자라난다.', 'It is skilled at slashing enemies with its claws. If broken, they start to grow back in a day.'),
  ('kanto', 29, 29, true, '온순한 성격이라 싸움을 좋아하지 않지만 작은 뿔에서 독이 나오므로 주의가 필요하다.', 'A mild-mannered Pokémon that does not like to fight. Beware—its small horn secretes venom.'),
  ('kanto', 30, 30, true, '보금자리 안에 있을 때는 언제나 가시가 들어가 있다. 마음이 편안해졌다는 증거다.', 'When resting deep in its burrow, its barbs always retract. This is proof that it is relaxed.'),
  ('kanto', 31, 31, true, '단단한 비늘에 뒤덮인 튼튼한 몸의 소유자. 비늘은 다시 자라는 것 같다.', 'Tough scales cover the sturdy body of this Pokémon. It appears that the scales grow in cycles.'),
  ('kanto', 32, 32, true, '언제나 커다란 귀를 세워서 주위의 낌새를 살핀다. 위험을 감지하면 독침을 사용한다.', 'Its large ears are always kept upright. If it senses danger, it will attack with a poisonous sting.'),
  ('kanto', 33, 33, true, '머리에 있는 뿔의 독소는 찌르는 순간의 충격으로 흘러나오는 구조다.', 'Its horn contains venom. If it stabs an enemy with the horn, the impact makes the poison leak out.'),
  ('kanto', 34, 34, true, '강철같은 피부를 활용한 몸통박치기는 강력하다. 뿔은 다이아몬드도 꿰뚫는다.', 'Its steel-like hide adds to its powerful tackle. Its horns are so hard, they can pierce a diamond.'),
  ('kanto', 35, 35, true, '모습과 행동이 사랑스러워서 인기가 높지만 수가 적어서인지 좀처럼 발견되지 않는다.', 'Adored for their cute looks and playfulness. They are thought to be rare, as they do not appear often.'),
  ('kanto', 36, 36, true, '자신들의 세계를 소중히 생각하고 있는 듯 좀처럼 사람 앞에 나타나지 않는 요정의 일종.', 'They appear to be very protective of their own world. It is a kind of fairy, rarely seen by people.'),
  ('kanto', 37, 37, true, '털과 꼬리가 아름답다. 성장하면 꼬리 끝이 갈라져서 갈래가 많아진다.', 'Both its fur and its tails are beautiful. As it grows, the tails split and form more tails.'),
  ('kanto', 38, 38, true, '9명의 성자가 합체하여 이 포켓몬으로 다시 태어났다는 전설이 남아 있다.', 'According to an enduring legend, nine noble saints were united and reincarnated as this Pokémon.'),
  ('kanto', 39, 39, true, '초롱초롱한 눈동자로 상대를 바라본 다음 이상하고 기분 좋은 노래를 불러서 잠들게 한다.', 'Uses its cute round eyes to enrapture its foe. It then sings a pleasing melody that lulls the foe to sleep.'),
  ('kanto', 40, 40, true, '탄력성이 뛰어난 몸은 크게 숨을 들이마시면 끝없이 부풀어 오른다.', 'Its body is very elastic. By inhaling deeply, it can continue to inflate itself without limit.'),
  ('kanto', 41, 41, true, '입에서 초음파를 내보내면서 나는 것은 앞에 무엇이 있는지 확인하면서 날기 때문이다.', 'Emits ultrasonic cries while it flies. They act as a sonar used to check for objects in its way.'),
  ('kanto', 42, 42, true, '어디선가 소리 없이 다가온다. 날카로운 이빨로 무는 동시에 피를 빨아들인다.', 'It attacks in a stealthy manner, without warning. Its sharp fangs are used to bite and to suck blood.'),
  ('kanto', 43, 43, true, '평범한 풀이라 생각하고 뽑으려 하면 울음소리가 들린다. 어쩐지 매우 오싹한 기분이 든다.', 'It may be mistaken for a clump of weeds. If you try to yank it out of the ground, it shrieks horribly.'),
  ('kanto', 44, 44, true, '강렬한 악취가 난다! 그럼에도 불구하고 1000명에 한 명 정도 이 냄새를 즐겨 맡는 사람이 있다.', 'Smells incredibly foul! However, around one out of a thousand people enjoy sniffing its nose-bending stink.'),
  ('kanto', 45, 45, true, '독성분의 꽃가루를 퍼뜨리기 위해 커다란 꽃잎을 흔들면 굉장한 소리도 함께 울려 퍼진다.', 'Flaps its broad flower petals to scatter its poisonous pollen. The flapping sound is very loud.'),
  ('kanto', 46, 46, true, '구멍을 파서 나무뿌리로부터 영양을 섭취하지만 대부분은 등에 있는 버섯에게 빼앗긴다.', 'Burrows under the ground to gnaw on tree roots. The mushrooms on its back absorb most of the nutrition.'),
  ('kanto', 47, 47, true, '계속 진액을 빨아 먹혀서 이제는 벌레가 아니라 등에 있는 버섯이 생각하고 있는 듯하다.', 'The bug host is drained of energy by the mushroom on its back. The mushroom appears to do all the thinking.'),
  ('kanto', 48, 48, true, '레이더 역할을 하는 큰 눈은 밝은 곳에서 보면 작은 눈이 모여서 이루어진 것임을 알 수 있다.', 'Its large eyes act as radar. In a bright place, you can see that they are clusters of many tiny eyes.'),
  ('kanto', 49, 49, true, '날개의 인분은 몸에 묻으면 좀처럼 떨어지지 않는다. 게다가 거기에서 독성분이 스며든다.', 'The powdery scales on its wings are hard to remove from skin. They also contain poison that leaks out on contact.'),
  ('kanto', 50, 50, true, '어두운 곳을 좋아한다. 거의 땅속에서 지내지만 동굴에서는 자주 얼굴을 내밀고 있다.', 'It prefers dark places. It spends most of its time underground, though it may pop up in caves.'),
  ('kanto', 51, 51, true, '세쌍둥이의 파워로 지하 100km까지 땅을 파고들어 간다. 이것이 지진의 원인이라는 보고도 있다.', 'A team of triplets that can burrow to a depth of 60 miles. It’s reported that this triggers an earthquake.'),
  ('kanto', 52, 52, true, '밤에 더 기운이 넘치는 것 같다. 둥글고 빛나는 것을 좋아해서 발견하면 줍지 않고는 못 배긴다.', 'Appears to be more active at night. It loves round and shiny things. It can’t stop itself from picking them up.'),
  ('kanto', 53, 53, true, '이마의 보석이 빛난다! 걷는 모습도 우아하고 왕녀와 같은 화려함이 있다.', 'The gem in its forehead glows on its own! It walks with all the grace and elegance of a proud queen.'),
  ('kanto', 54, 54, true, '항상 두통에 시달리고 있다. 염력을 사용하지만 자신의 의지인지 아닌지 알 수 없다.', 'Always tormented by headaches. It uses psychic powers, but whether it intends to do so is not known.'),
  ('kanto', 55, 55, true, '날씬하고 긴 팔다리와 발달한 큰 물갈퀴로 호수를 우아하게 헤엄친다.', 'Its long, slim limbs end in broad flippers. They are used for swimming gracefully in lakes.'),
  ('kanto', 56, 56, true, '몸이 가벼워 나무 위에서 생활한다. 사소한 일로 기분이 나빠져 주변에 있는 것에 덤벼든다.', 'An agile Pokémon that lives in trees. It angers easily and will not hesitate to attack anything.'),
  ('kanto', 57, 57, true, '주위에 아무도 없을 때만은 화를 내지 않고 있다. 그러나 그 모습을 보기가 어렵다.', 'It stops being angry only when nobody else is around. To view this moment is very difficult.'),
  ('kanto', 58, 58, true, '사람을 잘 따르는 성격이지만 영역에 들어온 상대에게는 격렬하게 짖는다.', 'A Pokémon with a friendly nature. However, it will bark fiercely at anything invading its territory.'),
  ('kanto', 59, 59, true, '동양의 전설의 포켓몬. 경쾌하게 달리는 그 모습에 반하는 자도 많다.', 'A legendary Pokémon in the East. Many people are charmed by the grace and beauty of its running.'),
  ('kanto', 60, 60, true, '배의 소용돌이 방향은 태어난 지방에 따라 다른 듯하다. 걷기보다 헤엄치기를 잘한다.', 'The direction of the spiral on the belly differs by area. It is more adept at swimming than walking.'),
  ('kanto', 61, 61, true, '공격당할 위기에 처하면 배에 있는 소용돌이를 사용해 상대를 잠들게 한 뒤 그 틈에 도망치는 듯하다.', 'Under attack, it uses its belly spiral to put the foe to sleep. It then makes its escape.'),
  ('kanto', 62, 62, true, '전신의 근육을 사용한 파워풀한 헤엄으로 세계 레벨급 선수도 앞질러 간다.', 'Swims powerfully using all the muscles in its body. It can even overtake world-class swimmers.'),
  ('kanto', 63, 63, true, '하루에 18시간을 잔다. 위험이 닥치면 잠든 상태에서도 순간이동해서 도망친다.', 'Sleeps 18 hours a day. If it senses danger, it will teleport itself to safety even as it sleeps.'),
  ('kanto', 64, 64, true, '윤겔라가 근처에 있으면 시계가 거꾸로 도는 등 이상한 일들이 일어나는 듯하다.', 'Many odd things happen if this Pokémon is close by. For example, it makes clocks run backward.'),
  ('kanto', 65, 65, true, '무엇이든 기억해 낸다. 체험한 모든 것을 잊지 않기에 머리가 좋은 것이다.', 'A Pokémon that can memorize anything. It never forgets what it learns—that’s why this Pokémon is smart.'),
  ('kanto', 66, 66, true, '몸집은 작지만 힘이 장사다. 게다가 다양한 격투기를 마스터해서 매우 강하다.', 'Very powerful in spite of its small size. Its mastery of many types of martial arts makes it very tough.'),
  ('kanto', 67, 67, true, '허리에 두른 파워 세이브 벨트를 풀면 그 누구도 근육몬의 기세를 막을 수 없다.', 'The belt around its waist holds back its energy. Without it, this Pokémon would be unstoppable.'),
  ('kanto', 68, 68, true, '하나만으로도 산을 움직일 수 있는 힘을 가진 팔을 4개 모두 사용하여 굉장한 펀치를 날린다.', 'One arm alone can move mountains. Using all four arms, this Pokémon fires off awesome punches.'),
  ('kanto', 69, 69, true, '온도가 높고 습기가 있는 장소를 좋아한다. 덩굴을 사용해 작은 벌레를 잡아먹는다.', 'Prefers hot and humid places. It ensnares tiny bugs with its vines and devours them.'),
  ('kanto', 70, 70, true, '배가 고프면 움직이는 것을 닥치는 대로 삼킨 다음 용해액으로 마무리한다.', 'When hungry, it swallows anything that moves. Its hapless prey is dissolved by strong acids.'),
  ('kanto', 71, 71, true, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Lures prey with the sweet aroma of honey. Swallowed whole, the prey is dissolved in a day, bones and all.'),
  ('kanto', 72, 72, true, '물가에 바싹 마른 상태로 발견될 때도 있지만 물에 담가주면 부활한다.', 'It can sometimes be found all dry and shriveled up on a beach. Toss it back into the sea to revive it.'),
  ('kanto', 73, 73, true, '80개의 촉수를 자유자재로 늘이고 줄여 먹이를 휘감은 뒤 독을 주입해서 약하게 만든다.', 'Its 80 tentacles can stretch and contract freely. They wrap around prey and weaken it with poison.'),
  ('kanto', 74, 74, true, '산길 등에 많이 서식한다. 실수로 밟으면 화를 내므로 주의가 필요하다.', 'Commonly found near mountain trails and the like. If you step on one by accident, it gets angry.'),
  ('kanto', 75, 75, true, '산길에서 자주 굴러다닌다. 가는 길에 무엇이 있든 전혀 신경 쓰지 않는다.', 'Often seen rolling down mountain trails. Obstacles are just things to roll straight over, not avoid.'),
  ('kanto', 76, 76, true, '탈피한 직후에는 전체가 하얗고 부드럽지만 금방 공기와 접촉해서 단단해진다.', 'Once it sheds its skin, its body turns tender and whitish. Its hide hardens when it’s exposed to air.'),
  ('kanto', 77, 77, true, '엄청난 점프 뒤에 오는 착지의 충격은 발굽과 다리의 근육으로 완화한다.', 'Capable of jumping incredibly high. Its hooves and sturdy legs absorb the impact of a hard landing.'),
  ('kanto', 78, 78, true, '그저 달리는 것을 좋아해서 자신보다 빠른 상대를 발견하면 전속력으로 쫓아간다.', 'Just loves to run. If it sees something faster than itself, it will give chase at top speed.'),
  ('kanto', 79, 79, true, '매우 멍청하고 움직임도 둔하다. 시간의 흐름을 의식하지 않고 느긋하게 살고 있다.', 'Incredibly slow and sluggish. It is quite content to loll about without worrying about the time.'),
  ('kanto', 80, 80, true, '바다 근처에서 느긋하게 산다. 만약 꼬리에 있는 셀러가 떨어지면 야돈으로 돌아간다.', 'Lives lazily by the sea. If the Shellder on its tail comes off, it becomes a Slowpoke again.'),
  ('kanto', 81, 81, true, '태어날 때부터 중력을 차단하는 능력을 가지고 있어 전자파를 내면서 공중을 이동한다.', 'It is hatched with the ability to defy gravity. It floats while emitting powerful electromagnetic waves.'),
  ('kanto', 82, 82, true, '알 수 없는 전파를 발신하고 있어 반경 1km 범위는 기온이 2도 오른다.', 'Generates strange radio signals. It raises the temperature by 3.6 degrees Fahrenheit within 3,300 feet.'),
  ('kanto', 83, 83, true, '줄기가 자라는 곳에 산다. 이상하게 수도 적어서 파오리의 수도 줄고 있는 듯하다.', 'They live where reedy plants grow. Farfetch’d are rarely seen, so it’s thought their numbers are decreasing.'),
  ('kanto', 84, 84, true, '날개가 짧아서 하늘을 나는 것은 서투르지만 대신 발달한 다리로 빠르게 달릴 수 있다.', 'Its short wings make flying difficult. Instead, this Pokémon runs at high speed on developed legs.'),
  ('kanto', 85, 85, true, '두두의 머리 중 한 쪽이 분열한 변종. 초원을 시속 60km로 달린다.', 'One of Doduo’s two heads splits to form a unique species. It runs close to 40 mph in prairies.'),
  ('kanto', 86, 86, true, '얼어붙을 정도로 추운 곳을 좋아한다. 영하 10도 정도의 물속에서 기분 좋게 헤엄친다.', 'Loves freezing-cold conditions. Relishes swimming in a frigid climate of around 14 degrees Fahrenheit.'),
  ('kanto', 87, 87, true, '온몸이 눈처럼 새하얗다. 추위에 강해 얼음이 떠 있는 바다도 기운차게 헤엄쳐 다닌다.', 'Its entire body is a snowy white. Unharmed by even intense cold, it swims powerfully in icy waters.'),
  ('kanto', 88, 88, true, '진흙이 뭉쳐져서 태어났다. 악취 때문에 건드릴 엄두가 안 나고 지나간 자리에는 풀 한 포기 나지 않는다.', 'Made of congealed sludge. It smells too putrid to touch. Even weeds won’t grow in its path.'),
  ('kanto', 89, 89, true, '악취가 심하다! 기절할 정도로 강렬하지만 질뻐기는 코가 퇴화해서 냄새를 맡지 못한다.', 'Smells so awful, it can cause fainting. Through degeneration of its nose, it lost its sense of smell.'),
  ('kanto', 90, 90, true, '어떤 공격에도 견디는 단단한 껍질을 가졌지만 열면 부드러운 몸이 드러난다.', 'The shell can withstand any attack. However, when it is open, the tender body is exposed.'),
  ('kanto', 91, 91, true, '다이아몬드보다 단단한 껍질로 몸을 지킬 뿐만 아니라 달린 가시를 쏘아 대기 때문에 상당히 벅찬 상대다.', 'For protection, it uses its harder-than-diamond shell. It also shoots spikes from the shell.'),
  ('kanto', 92, 92, true, '오래되어 아무도 살지 않는 건물에 나타나는 듯하다. 형태는 모호하고 가스 같다.', 'Said to appear in decrepit, deserted buildings. It has no real shape, as it appears to be made of a gas.'),
  ('kanto', 93, 93, true, '핥아서 상대의 생명을 흡수한다. 상대는 몸을 계속 벌벌 떨다가 결국에는 죽음에 이른다고 한다.', 'By licking, it saps the victim’s life. It causes shaking that won’t stop until the victim’s demise.'),
  ('kanto', 94, 94, true, '갑자기 한기를 느꼈다면 팬텀이 가까이 있는 것이다. 어쩌면 저주를 걸지도 모른다.', 'A Gengar is close by if you feel a sudden chill. It may be trying to lay a curse on you.'),
  ('kanto', 95, 95, true, '땅속을 엄청난 기세로 뚫고 나아가며 먹이를 찾는다. 지나간 곳은 디그다의 보금자리가 된다.', 'Burrows at high speed in search of food. The tunnels it leaves are used as homes by Diglett.'),
  ('kanto', 96, 96, true, '언제나 함께 잠들다 보면 가끔 옛날에 먹었던 꿈을 보여줄 때가 있다.', 'If you sleep by it all the time, it will sometimes show you dreams it had eaten in the past.'),
  ('kanto', 97, 97, true, '우연히 마주쳤을 때 다른 곳으로 눈을 돌리지 않으면 위험하다. 손에 든 추로 잠재워 버린다.', 'Avoid eye contact if you come across one. It will try to put you to sleep by using its pendulum.'),
  ('kanto', 98, 98, true, '강력한 무기인 집게는 공격하다 드물게 떨어지지만 나중에 금방 자라난다.', 'Its pincers are superb weapons. They sometimes break off during battle, but they grow back fast.'),
  ('kanto', 99, 99, true, '한쪽만 거대해진 집게는 강철 같은 단단함과 1만 마력의 힘을 지녔지만 너무 무겁다.', 'One claw grew massively and is as hard as steel. It has 10,000-horsepower strength. However, it is too heavy.'),
  ('kanto', 100, 100, true, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'It is said to camouflage itself as a Poké Ball. It will self-destruct with very little stimulus.'),
  ('kanto', 101, 101, true, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'Stores electrical energy inside its body. Even the slightest shock could trigger a huge explosion.'),
  ('kanto', 102, 102, true, '알 하나하나가 서로를 끌어당겨서 회전한다. 6개가 아니면 불안해한다.', 'The heads attract each other and spin around. There must be six heads for it to maintain balance.'),
  ('kanto', 103, 103, true, '울음소리가 시끄러운 것은 3개의 머리가 좋아하는 것에 대해 따로따로 생각하고 있기 때문이다.', 'Its cries are very noisy. This is because each of the three heads thinks about whatever it likes.'),
  ('kanto', 104, 104, true, '죽은 어미의 뼈를 뒤집어썼다. 울음소리는 뼈 안에서 울려서 구슬픈 멜로디가 된다.', 'Wears the skull of its deceased mother. Its cries echo inside the skull and come out as a sad melody.'),
  ('kanto', 105, 105, true, '몸집은 작고 약했지만 뼈를 능숙하게 사용해서 싸우는 흉포한 성격이 되었다.', 'Small and weak, this Pokémon is adept with its bone club. It has grown more vicious over the ages.'),
  ('kanto', 106, 106, true, '킥이 명중하는 순간! 발바닥이 다이아몬드처럼 단단해져서 상대를 파괴한다.', 'When kicking, the sole of its foot turns as hard as a diamond on impact and destroys its enemy.'),
  ('kanto', 107, 107, true, '비틀면서 뚫는 듯한 펀치 공격! 콘크리트 벽이 드릴 모양으로 깎여나가 구멍이 뚫린다.', 'Punches in corkscrew fashion. It can punch its way through a concrete wall like a drill.'),
  ('kanto', 108, 108, true, '2m나 되는 긴 혀는 앞다리보다 능숙하게 움직일 수 있다. 혀로 핥으면 상대가 마비된다.', 'Its tongue spans almost seven feet and moves more freely than its forelegs. Its licks can cause paralysis.'),
  ('kanto', 109, 109, true, '더운 곳에서는 몸 안의 가스가 부풀어 올라 파열될 위험성이 있으므로 주의해야 한다.', 'In hot places, its internal gases could expand and explode without any warning. Be very careful!'),
  ('kanto', 110, 110, true, '쓰레기 속에 포함된 독가스, 세균, 먼지를 흡수하며 살고 있다.', 'This Pokémon lives and grows by absorbing poison gas, dust, and germs that exist inside garbage.'),
  ('kanto', 111, 111, true, '단순해서 한가지 생각밖에 하지 못한다. 돌진을 시작하면 잠들 때까지 멈추지 않는다.', 'A Pokémon with a one-track mind. Once it charges, it won’t stop running until it falls asleep.'),
  ('kanto', 112, 112, true, '뒷다리만으로 걸을 수 있게 되어 지능이 발달했다. 갑옷 같은 피부는 마그마에도 견딘다.', 'Its brain developed when it began walking on its hind legs. Its armor-like hide even repels molten lava.'),
  ('kanto', 113, 113, true, '상처 입은 자를 발견하면 영양 만점인 알을 나눠주는 상냥한 포켓몬.', 'A gentle and kindhearted Pokémon that shares its nutritious eggs if it sees an injured Pokémon.'),
  ('kanto', 114, 114, true, '몸이 파란 덩굴에 싸여 있어 정체를 알 수 없다. 덩굴은 계속해서 자란다고 한다.', 'Its identity is obscured by masses of thick blue vines. The vines are said to never stop growing.'),
  ('kanto', 115, 115, true, '배의 주머니에서 새끼를 키운다. 새끼를 지키기 위해서라면 어떤 상대든지 맞서 싸운다.', 'Raises its young in its belly pouch. Won’t run from any fight to keep its young protected.'),
  ('kanto', 116, 116, true, '신변에 위험을 느끼면 입에서 물이나 특수한 먹물을 힘차게 뿜어낸다.', 'If it senses any danger, it will vigorously spray water or a special type of ink from its mouth.'),
  ('kanto', 117, 117, true, '등지느러미를 건드리면 마비된다. 잘 때는 물살에 떠내려가지 않도록 꼬리를 산호에 휘감는다.', 'Touching the back fin causes numbness. It hooks its tail to coral to stay in place while sleeping.'),
  ('kanto', 118, 118, true, '알을 낳을 때가 되면 강이나 폭포를 오르는 콘치 무리의 모습을 볼 수 있다.', 'When it is time for them to lay eggs, they can be seen swimming up rivers and falls in large groups.'),
  ('kanto', 119, 119, true, '머리의 뿔로 강바닥에 있는 돌을 파내어 둥지를 만드는 것은 수컷의 역할이다.', 'It is the male’s job to make a nest by carving out boulders in a stream using the horn on its head.'),
  ('kanto', 120, 120, true, '몸의 중심 부분만 남아 있으면 아무리 잘게 잘려도 재생한다고 한다.', 'As long as the center section is unharmed, this Pokémon can grow back fully even if it is chopped to bits.'),
  ('kanto', 121, 121, true, '코어라고 불리는 중심 부분이 일곱 빛깔로 빛나는 것은 통신을 하고 있기 때문이라고 전해진다.', 'The center section is named the core. People think it is communicating when it glows in seven colors.'),
  ('kanto', 122, 122, true, '팬터마임이 특기로 언제나 연습을 하고 있다. 없는 것도 그곳에 있다고 믿게 만든다.', 'Always practicing its pantomime act. It makes enemies believe something exists that really doesn’t.'),
  ('kanto', 123, 123, true, '풀숲에서 갑자기 튀어나와 예리한 낫으로 베어 가르는 모습은 마치 닌자 같다.', 'Leaps out of tall grass and slices prey with its scythes. The movement looks like that of a ninja.'),
  ('kanto', 124, 124, true, '특유의 리듬감을 갖고 있다. 춤추듯 경쾌하게 움직이며 허리를 흔들며 걷는다.', 'Appears to move to a rhythm of its own, as if it were dancing. It wiggles its hips as it walks.'),
  ('kanto', 125, 125, true, '대규모 정전이 일어났을 땐 에레브가 발전소의 전기를 먹은 것임이 틀림없다.', 'If a major power outage occurs, it is certain that this Pokémon has eaten electricity at a power plant.'),
  ('kanto', 126, 126, true, '화산의 분화구에서 태어났다. 전신이 불타고 있어 불구슬과 구분이 안된다.', 'Born in an active volcano. Its body is always cloaked in flames, so it looks like a big ball of fire.'),
  ('kanto', 127, 127, true, '뿔로 집은 다음 있는 힘껏 조인다! 추워지면 움직일 수 없게 되므로 따뜻한 곳에 산다.', 'Grips its prey in its pincers and squeezes hard! It can’t move if it’s cold out, so it lives in warm places.'),
  ('kanto', 128, 128, true, '넘치는 체력의 난동꾼. 달리기 시작하면 몸통박치기를 할 때까지 끝없이 돌진한다.', 'A rowdy Pokémon with a lot of stamina. Once running, it won’t stop until it hits something.'),
  ('kanto', 129, 129, true, '못 미덥기로 유명한 포켓몬. 바다, 강, 연못, 물웅덩이 등 다양한 곳에서 헤엄치고 있다.', 'Famous for being very unreliable. It can be found swimming in seas, lakes, rivers, and shallow puddles.'),
  ('kanto', 130, 130, true, '야만스럽고 파괴적인 성격이다. 먼 옛날 마을을 불태워버렸다는 기록이 있는 공포의 포켓몬.', 'Brutally vicious and enormously destructive. Known for totally destroying cities in ancient times.'),
  ('kanto', 131, 131, true, '인간의 말을 이해하는 착한 마음의 소유자다. 사람을 등에 태우고 바다를 건넌다.', 'A gentle soul that can understand human speech. It can ferry people across the sea on its back.'),
  ('kanto', 132, 132, true, '상대를 본 순간 몸이 녹는 것처럼 변화하기 시작한다. 거의 똑같은 모습으로 변신한다.', 'When it spots an enemy, its body transfigures into an almost-perfect copy of its opponent.'),
  ('kanto', 133, 133, true, '다양한 모습으로 진화한다. 이브이의 유전자는 진화의 비밀을 밝혀낼 열쇠다.', 'It can evolve into a variety of forms. Eevee’s genes are the key to solving the mysteries of Pokémon evolution.'),
  ('kanto', 134, 134, true, '세포 조직이 물 분자와 비슷하기 때문에 물에 녹아들면 모습이 보이지 않게 된다.', 'Its cell structure is similar to water molecules. It melts into the water and becomes invisible.'),
  ('kanto', 135, 135, true, '약간의 자극으로 울거나 화를 낸다. 또한 감정이 변할 때마다 전기가 모인다.', 'A sensitive Pokémon that easily becomes sad or angry. Every time its mood changes, it charges power.'),
  ('kanto', 136, 136, true, '체내에 불꽃 주머니가 있어 들이마신 숨을 1700도의 불꽃으로 바꿔 입에서 뿜어낸다.', 'It has a flame chamber inside its body. It inhales, then breathes out fire that is over 3,000 degrees Fahrenheit.'),
  ('kanto', 137, 137, true, '유일하게 우주까지 날아갈 수 있는 포켓몬으로 기대를 모으고 있지만 아직 성공한 사례는 없다.', 'The only Pokémon that people anticipate can fly into space. None has managed the feat yet, however.'),
  ('kanto', 138, 138, true, '10개의 다리를 자유자재로 구불거리며 고대의 바다를 떠돌던 포켓몬의 화석을 복원했다.', 'An ancient Pokémon that was recovered from a fossil. It swam by cleverly twisting its 10 tentacles about.'),
  ('kanto', 139, 139, true, '날카로운 이빨을 가졌지만 껍질이 너무 커서 제대로 움직이지 못해 멸종한 듯하다.', 'Its sharp beak rings its mouth. Its shell was too big for it to move freely, so it became extinct.'),
  ('kanto', 140, 140, true, '화석에서 재생된 포켓몬. 해저에 숨어서 등에 달린 눈으로 주변을 살폈던 것 같다.', 'A Pokémon that was recovered from a fossil. It used the eyes on its back while hiding on the seafloor.'),
  ('kanto', 141, 141, true, '날렵한 몸으로 재빠르게 헤엄친다. 잡은 먹이는 낫으로 베어 체액을 빨아들이는 듯하다.', 'A slim and fast swimmer. It sliced its prey with its sharp sickles and drank the body fluids.'),
  ('kanto', 142, 142, true, '호박에서 추출한 유전자를 연구해서 부활시킨 먼 옛날의 사나운 포켓몬.', 'A savage Pokémon that died out in ancient times. It was resurrected using DNA taken from amber.'),
  ('kanto', 143, 143, true, '약간 곰팡이가 피어 있어도 신경 쓰지 않고 먹어 치운다. 배탈이 나는 일도 없다.', 'Will eat anything, even if the food happens to be a little moldy. It never gets an upset stomach.'),
  ('kanto', 144, 144, true, '겨울 하늘의 공기 중에 있는 수분을 얼려서 눈을 내리게 하는 전설의 새포켓몬.', 'A legendary bird Pokémon. It freezes water that is contained in winter air and makes it snow.'),
  ('kanto', 145, 145, true, '하늘이 어두워지고 벼락이 연속으로 떨어지면 이윽고 전설의 포켓몬이 나타난다.', 'This legendary bird Pokémon is said to appear when the sky turns dark and lightning showers down.'),
  ('kanto', 146, 146, true, '밤하늘조차 붉게 물들일 정도로 격렬하게 타오르는 날개로 날갯짓하는 전설의 새포켓몬.', 'A legendary bird Pokémon. As it flaps its flaming wings, even the night sky will turn red.'),
  ('kanto', 147, 147, true, '오랫동안 환상 속의 존재로 여겨졌지만 최근 누군가가 낚시에 성공하여 그 존재가 확인되었다.', 'Long thought to be a myth, this Pokémon’s existence was only recently confirmed by a fisherman who caught one.'),
  ('kanto', 148, 148, true, '목격한 사람의 말에 의하면 몸에서 오라가 나와서 신비로웠다고 한다.', 'According to a witness, its body was surrounded by a strange aura that gave it a mystical look.'),
  ('kanto', 149, 149, true, '넓은 바다 어딘가를 거처로 삼아 날아서 이동한다고 전해지지만 어디까지나 소문에 지나지 않는다.', 'It is said that this Pokémon lives somewhere in the sea and that it flies. However, these are only rumors.'),
  ('kanto', 150, 150, true, '뮤의 유전자와 거의 같다. 하지만 크기도 성격도 무서울 정도로 다르다.', 'Its DNA is almost the same as Mew’s. However, its size and disposition are vastly different.'),
  ('kanto', 151, 151, true, '현미경으로 관찰하면 매우 짧고 가는 털이 촘촘하게 나 있다.', 'When viewed through a microscope, this Pokémon’s short, fine, delicate hair can be seen.'),
  ('johto', 1, 152, true, '잎사귀를 휘둘러 상대를 위협하지만 잎사귀에서 달콤한 향기가 풍겨 나와 서로 온화한 분위기가 된다.', 'A sweet aroma gently wafts from the leaf on its head. It is docile and loves to soak up sunrays.'),
  ('johto', 2, 153, true, '목 주변의 둥그렇게 말린 잎사귀 안에는 작은 새싹 한 개가 나 있다. 그 향기는 사람을 기운 나게 한다.', 'The scent of spices comes from around its neck. Somehow, sniffing it makes you want to fight.'),
  ('johto', 3, 154, true, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The aroma that rises from its petals contains a substance that calms aggressive feelings.'),
  ('johto', 4, 155, true, '등에서 불꽃을 내뿜어 몸을 지킨다. 화났을 때의 불꽃은 기운차지만 지쳤을 때는 불완전연소한다.', 'It is timid, and always curls itself up in a ball. If attacked, it flares up its back for protection.'),
  ('johto', 5, 156, true, '불꽃의 기세와 열풍으로 위협한다. 재빠른 몸동작으로 상대의 공격을 피하면서 동시에 불꽃으로 태운다.', 'Be careful if it turns its back during battle. It means that it will attack with the fire on its back.'),
  ('johto', 6, 157, true, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'If its rage peaks, it becomes so hot that anything that touches it will instantly go up in flames.'),
  ('johto', 7, 158, true, '몸은 작지만 턱의 힘은 강하다. 리아코 나름은 살포시 물려고 하지만 큰 상처를 입힐 정도의 힘이 있다.', 'Its powerful, well-developed jaws are capable of crushing anything. Even its Trainer must be careful.'),
  ('johto', 8, 159, true, '한 번 물고 늘어지면 절대로 놓지 않는다. 이빨 끝이 낚싯바늘처럼 휘어져 있어서 한 번 들어가면 빠지지 않는다.', 'If it loses a fang, a new one grows back in its place. There are always 48 fangs lining its mouth.'),
  ('johto', 9, 160, true, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'When it bites with its massive and powerful jaws, it shakes its head and savagely tears its victim up.'),
  ('johto', 10, 16, true, '얌전한 성격이라 습격당해도 반격하지 않고 모래를 뿌려서 몸을 지키는 경우가 많다.', 'It usually hides in tall grass. Because it dislikes fighting, it protects itself by kicking up sand.'),
  ('johto', 11, 17, true, '어마어마한 체력의 소유자로 넓은 영역을 날아다니며 먼 곳까지 먹이를 찾으러 간다.', 'It has outstanding vision. However high it flies, it is able to distinguish the movements of its prey.'),
  ('johto', 12, 18, true, '마하2의 속도로 비행하여 먹이를 찾는다. 그 커다란 발톱은 무기로서도 두려움의 대상이다.', 'Its well-developed chest muscles make it strong enough to whip up a gusty windstorm with just a few flaps.'),
  ('johto', 13, 21, true, '높이 나는 것에 서투르다. 영역을 지키기 위해 맹렬한 스피드로 날아다닌다.', 'It flaps its short wings to flush out insects from tall grass. It then plucks them with its stubby beak.'),
  ('johto', 14, 22, true, '옛날부터 살고 있는 포켓몬. 조금이라도 위험을 감지하면 하늘 높이 날아가 버린다.', 'It shoots itself suddenly high into the sky, then plummets down in one fell swoop to strike its prey.'),
  ('johto', 15, 163, true, '언제나 정해진 시간이 되면 울음소리를 내어 시계 대용으로 데리고 다니는 트레이너도 있다.', 'It always stands on one foot. It changes feet so fast, the movement can rarely be seen.'),
  ('johto', 16, 164, true, '무언가를 생각하기 시작하면 목을 180도 회전시켜 두뇌 회전을 높인다.', 'Its eyes are specially adapted. They concentrate even faint light and enable it to see in the dark.'),
  ('johto', 17, 19, true, '2개의 이빨로 뭐든지 일단 갉고 본다. 1마리를 발견했다면 그곳에 40마리는 살고 있을 것이다.', 'It eats anything. Wherever food is available, it will settle down and produce offspring continuously.'),
  ('johto', 18, 20, true, '뒷다리에 달린 작은 물갈퀴로 강을 헤엄치는 이유는 물속에 있는 먹이를 잡기 위해서다.', 'Gnaws on anything with its tough fangs. It can even topple concrete buildings by gnawing on them.'),
  ('johto', 19, 161, true, '잠잘 때는 교대로 망을 본다. 위험을 탐지하면 동료를 깨운다. 무리에서 떨어지면 무서워서 자지 못한다.', 'A very cautious Pokémon, it raises itself up using its tail to get a better view of its surroundings.'),
  ('johto', 20, 162, true, '적에게 습격당해도 좁은 틈으로 쑥 들어가서 도망갈 수 있다. 팔다리는 짧지만 매우 날쌔다.', 'It makes a nest to suit its long and skinny body. The nest is impossible for other Pokémon to enter.'),
  ('johto', 21, 172, true, '볼의 전기 주머니가 작아서 조금이라도 전기가 넘치게 되면 자기 자신이 감전되어 버린다.', 'It is not yet skilled at storing electricity. It may send out a jolt if amused or startled.'),
  ('johto', 22, 25, true, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'This intelligent Pokémon roasts hard berries with electricity to make them tender enough to eat.'),
  ('johto', 23, 26, true, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'When its electricity builds, its muscles are stimulated, and it becomes more aggressive than usual.'),
  ('johto', 24, 10, true, '다리는 짧지만 빨판으로 되어 있어 비탈길이나 벽에서도 지치지 않고 나아간다.', 'For protection, it releases a horrible stench from the antennae on its head to drive away enemies.'),
  ('johto', 25, 11, true, '단단한 껍질로 둘러싸여 있지만 안은 부드럽기 때문에 강한 공격에는 버티지 못한다.', 'Inside the shell, it is soft and weak as it prepares to evolve. It stays motionless in the shell.'),
  ('johto', 26, 12, true, '매일 꿀을 모으러 다닌다. 다리의 솜털에 꿀을 발라 둥지로 가지고 가는 습성이 있다.', 'It collects honey every day. It rubs honey onto the hairs on its legs to carry it back to its nest.'),
  ('johto', 27, 13, true, '머리에 날카로운 침을 지니고 있다. 우거진 숲이나 풀밭에 숨어 끊임없이 풀잎을 먹고 있다.', 'Its poison stinger is very powerful. Its bright-colored body is intended to warn off its enemies.'),
  ('johto', 28, 14, true, '스스로는 거의 움직일 수 없지만 위험해지면 침을 세워서 독을 뿜을 때도 있는 듯하다.', 'Although it is a cocoon, it can move a little. It can extend its poison barb if it is attacked.'),
  ('johto', 29, 15, true, '양손과 엉덩이에 있는 3개의 독침으로 상대를 찌르고 찌르고 또 찌르며 공격한다.', 'It can take down any opponent with its powerful poison stingers. It sometimes attacks in swarms.'),
  ('johto', 30, 165, true, '매우 겁이 많은 포켓몬이다. 동료와 함께 리플렉터를 펼쳐서 보금자리를 지키고 있다.', 'It is very timid. It will be afraid to move if it is alone. But it will be active if it is in a group.'),
  ('johto', 31, 166, true, '반짝이는 가루를 흩뿌리며 밤하늘을 난다. 가루가 몸에 붙으면 좋은 일이 생긴다고 전해진다.', 'When the stars flicker in the night sky, it flutters about, scattering a glowing powder.'),
  ('johto', 32, 167, true, '이빨의 독은 그다지 강하진 않지만 둥지에 걸려서 움직일 수 없는 먹이를 약하게 만들기에는 충분하다.', 'It lies still in the same pose for days in its web, waiting for its unsuspecting prey to wander close.'),
  ('johto', 33, 168, true, '실을 뿜어서 먹이를 잡는다. 밤이 되면 둥지를 떠나 적극적으로 사냥에 나선다.', 'It spins string not only from its rear but also from its mouth. It’s hard to tell which end is which.'),
  ('johto', 34, 74, true, '산길 등에 많이 서식한다. 실수로 밟으면 화를 내므로 주의가 필요하다.', 'Most people may not notice, but a closer look should reveal that there are many GEODUDE around.'),
  ('johto', 35, 75, true, '산길에서 자주 굴러다닌다. 가는 길에 무엇이 있든 전혀 신경 쓰지 않는다.', 'With a free and uncaring nature, it doesn’t mind if pieces break off while it rolls down mountains.'),
  ('johto', 36, 76, true, '탈피한 직후에는 전체가 하얗고 부드럽지만 금방 공기와 접촉해서 단단해진다.', 'It sheds its skin once a year. The discarded shell immediately hardens and crumbles away.'),
  ('johto', 37, 41, true, '볕이 들지 않는 동굴에 산다. 아침이 되면 동료들끼리 모여 서로의 온기를 나누면서 잔다.', 'While flying, it constantly emits ultrasonic waves from its mouth to check its surroundings.'),
  ('johto', 38, 42, true, '작은 다리로 능숙하게 걷는다. 자고 있는 먹이에게 살며시 다가가 이빨을 꽂아 피를 빨아먹는다.', 'However hard its victim’s hide may be, it punctures with sharp fangs and gorges itself with blood.'),
  ('johto', 39, 169, true, '4장의 날개를 자유자재로 움직이며 날갯짓한다. 좁은 동굴에서도 속도를 늦추지 않고 날아다닐 수 있다.', 'It flies so silently through the dark on its four wings that it may not be noticed even when nearby.'),
  ('johto', 40, 173, true, '실루엣이 별 모양이다. 그 때문에 별똥별을 타고 온다고 여겨진다.', 'Because of its unusual, starlike silhouette, people believe that it came here on a meteor.'),
  ('johto', 41, 35, true, '애교 있는 몸동작과 울음소리로 귀엽다고 많은 인기를 누리는 포켓몬. 그러나 좀처럼 눈에 띄지 않는다.', 'The moonlight that it stores in the wings on its back apparently gives it the ability to float in midair.'),
  ('johto', 42, 36, true, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'With its acute hearing, it can pick up sounds from far away. It usually hides in quiet places.'),
  ('johto', 43, 174, true, '부드러운 몸으로 통통 튀며 움직인다. 체온이 오르면 몸은 짙은 핑크색이 된다.', 'It has a very soft body. If it starts to roll, it will bounce all over and be impossible to stop.'),
  ('johto', 44, 39, true, '목소리 파장을 자유자재로 바꾸어 들으면 반드시 잠드는 신비한 멜로디를 노래한다.', 'If it inflates to sing a lullaby, it can perform longer and cause sure drowsiness in its audience.'),
  ('johto', 45, 40, true, '얇고 고운 털을 가졌다. 특히 이마에 동그랗게 말린 털은 하늘을 날 듯한 최고의 감촉을 지녔다.', 'Their fur feels so good that if two of them snuggle together, they won’t want to be separated.'),
  ('johto', 46, 175, true, '행운의 상징이다. 껍질 안에는 행복이 가득 담겨 있다고 한다.', 'The shell seems to be filled with joy. It is said that it will share good luck when treated kindly.'),
  ('johto', 47, 176, true, '상냥한 사람 곁에 있지 않으면 기운을 내지 못한다. 날개를 움직이지 않고도 공중에 뜰 수 있다.', 'They say that it will appear before kindhearted, caring people and shower them with happiness.'),
  ('johto', 48, 27, true, '땅을 파서 굴을 만든다. 땅속의 단단한 바위도 날카로운 발톱으로 부수며 파고들어 간다.', 'If it fell from a great height, this Pokémon could save itself by rolling into a ball and bouncing.'),
  ('johto', 49, 28, true, '날카로운 발톱으로 찍으며 나무에 오른다. 아래에서 기다리는 모래두지들에게 나무열매를 떨어뜨려 나눠준다.', 'In an attempt to hide itself, it will run around at top speed to kick up a blinding dust storm.'),
  ('johto', 50, 23, true, '성장할수록 점점 길어진다. 밤에는 나뭇가지에 몸을 돌돌 말고 쉰다.', 'It can freely detach its jaw to swallow large prey whole. It can become too heavy to move, however.'),
  ('johto', 51, 24, true, '무서워 보이는 배의 무늬는 연구 결과 6종류 정도의 패턴이 확인되었다.', 'Transfixing prey with the face-like pattern on its belly, it binds and poisons the frightened victim.'),
  ('johto', 52, 206, true, '미로 같은 굴에 산다. 흙냄새로 자신이 있는 곳을 알 수 있어 절대 길을 잃지 않는다.', 'When spotted, this Pokémon escapes backward by furiously boring into the ground with its tail.'),
  ('johto', 53, 179, true, '솜털이 마찰하여 전기가 모인다. 귀엽다고 맨손으로 만지면 따끔하게 저리고 아프다.', 'If static electricity builds in its body, its fleece doubles in volume. Touching it will shock you.'),
  ('johto', 54, 180, true, '푹신푹신한 털에 전기를 저장한다. 너무 많이 저장해서 여기저기 반질반질하게 털이 빠져 버렸다.', 'As a result of storing too much electricity, it developed patches where even downy wool won’t grow.'),
  ('johto', 55, 181, true, '꼬리는 강하고 밝게 빛난다. 뱃사람들의 길잡이로서 옛날부터 소중히 여겨져 왔다.', 'The tail’s tip shines brightly and can be seen from far away. It acts as a beacon for lost people.'),
  ('johto', 56, 194, true, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'This Pokémon lives in cold water. It will leave the water to search for food when it gets cold outside.'),
  ('johto', 57, 195, true, '몸은 항상 미끄럽다. 헤엄칠 때마다 강바닥에 머리를 부딪치지만 신경 쓰지 않는다.', 'This carefree Pokémon has an easy-going nature. While swimming, it always bumps into boat hulls.'),
  ('johto', 58, 92, true, '몸은 옅은 가스로 되어 있어 어디든지 숨어들어 가지만 바람이 불면 날아가 버린다.', 'With its gas-like body, it can sneak into any place it desires. However, it can be blown away by wind.'),
  ('johto', 59, 93, true, '어둠 속에서 아무도 없는데도 누군가가 보고 있다는 느낌이 들면 그곳에 고우스트가 있는 것이다.', 'In total darkness, where nothing is visible, HAUNTER lurks, silently stalking its next victim.'),
  ('johto', 60, 94, true, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'It steals heat from its surroundings. If you feel a sudden chill, it is certain that a GENGAR appeared.'),
  ('johto', 61, 201, true, '고대 문자를 닮은 모습의 포켓몬이다. 먼저 생겨난 것은 문자인가 안농인가. 연구 중이지만 아직도 수수께끼다.', 'Their shapes look like hieroglyphs on ancient tablets. It is said that the two are somehow related.'),
  ('johto', 62, 95, true, '크고 튼튼한 몸을 뒤틀고 꼬아서 시속 80km로 힘차게 땅을 파나간다.', 'It twists and squirms through the ground. The thunderous roar of its tunneling echoes a long way.'),
  ('johto', 63, 208, true, '흙과 함께 삼킨 강철이 축적되어 몸이 변화한 것이라 여겨지고 있다.', 'Its body has been compressed deep under the ground. As a result, it is even harder than a diamond.'),
  ('johto', 64, 69, true, '온도가 높고 습기가 있는 장소를 좋아한다. 덩굴을 사용해 작은 벌레를 잡아먹는다.', 'Even though its body is extremely skinny, it is blindingly fast when catching its prey.'),
  ('johto', 65, 70, true, '배가 고프면 움직이는 것을 닥치는 대로 삼킨 다음 용해액으로 마무리한다.', 'Even though it is filled with acid, it does not melt because it also oozes a protective fluid.'),
  ('johto', 66, 71, true, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Acid that has dissolved many prey becomes sweeter, making it even more effective at attracting prey.'),
  ('johto', 67, 187, true, '바람을 타고 둥둥 떠다니는 포켓몬이다. 강풍의 기척을 느끼면 동료끼리 잎사귀를 휘감아 날아가지 않도록 준비한다.', 'To keep from being blown away by the wind, they gather in clusters. But they do enjoy gentle breezes.'),
  ('johto', 68, 188, true, '기온이 18도를 넘으면 꽃이 핀다. 온도에 따라 꽃이 피는 모습이 바뀌어서 온도계 대신 쓰기도 한다.', 'The bloom on top of its head opens and closes as the temperature fluctuates up and down.'),
  ('johto', 69, 189, true, '따뜻한 남풍을 타고 바다를 건너 외국까지 날아가는 포켓몬이다. 차가운 공기에 닿으면 땅에 내려온다.', 'Once it catches the wind, it deftly controls its cotton-puff spores-- it can even float around the world.'),
  ('johto', 70, 46, true, '구멍을 파서 나무뿌리로부터 영양을 섭취하지만 대부분은 등에 있는 버섯에게 빼앗긴다.', 'It is doused with mushroom spores when it is born. As its body grows, mushrooms sprout from its back.'),
  ('johto', 71, 47, true, '계속 진액을 빨아 먹혀서 이제는 벌레가 아니라 등에 있는 버섯이 생각하고 있는 듯하다.', 'It stays mostly in dark, damp places, the preference not of the bug, but of the big mushroom on its back.'),
  ('johto', 72, 60, true, '유속이 빠른 강에서는 두꺼운 입술을 흡반처럼 사용해 바위에 달라붙는다.', 'Because it is inept at walking on its newly grown legs, it always swims around in water.'),
  ('johto', 73, 61, true, '미끈미끈한 점액 형태의 땀을 흘린다. 적에게 붙잡혀도 스르륵 빠져나와 도망친다.', 'The swirl on its belly subtly undulates. Staring at it may gradually cause drowsiness.'),
  ('johto', 74, 62, true, '헤엄뿐만 아니라 격투기도 특기다. 단련한 팔로 호쾌하게 펀치를 날린다.', 'This strong and skilled swimmer is even capable of crossing the Pacific Ocean just by kicking.'),
  ('johto', 75, 186, true, '수컷의 울음소리가 더 크다. 나지막하고 위협적인 목소리로 우는 왕구리가 암컷에게 인기다.', 'If POLIWAG and POLIWHIRL hear its echoing cry, they respond by gathering from far and wide.'),
  ('johto', 76, 129, true, '유속이 빠른 곳에서는 그저 떠내려갈 뿐인 약하고 한심한 포켓몬이다.', 'An underpowered, pathetic Pokémon. It may jump high on rare occasions, but usually not more than seven feet.'),
  ('johto', 77, 130, true, '한번 난동부리기 시작한 갸라도스는 태풍이 사납게 휘몰아쳐도 모든 것을 다 태워버린다.', 'They say that during past strife, GYARADOS would appear and leave blazing ruins in its wake.'),
  ('johto', 78, 118, true, '등지느러미와 가슴지느러미가 근육처럼 발달하여 물속을 5노트의 속도로 헤엄친다.', 'Its dorsal, pectoral and tail fins wave elegantly in water. That is why it is known as the water dancer.'),
  ('johto', 79, 119, true, '뿔로 강바닥의 바위를 파헤쳐 둥지를 만드는 이유는 낳은 알이 떠내려가지 않도록 하기 위함이다.', 'During spawning season, SEAKING gather from all over, causing rivers to appear a brilliant red.'),
  ('johto', 80, 79, true, '꼬리를 물에 담가두면 단맛이 배어 나오기 때문에 이를 미끼로 포켓몬을 유인해서 낚는다.', 'It lazes vacantly near water. If something bites its tail, it won’t even notice for a whole day.'),
  ('johto', 81, 80, true, '셀러에게 물린 충격으로 두 발로 걸을 수 있게 되었다. 셀러가 떨어지면 야돈으로 돌아간다고 한다.', 'If the tail-biting SHELLDER is thrown off in a harsh battle, it reverts to being an ordinary SLOWPOKE.'),
  ('johto', 82, 199, true, '아무리 어려운 문제를 물어봐도 모두 해결해주지만 그 누구도 야도킹의 말을 이해하지 못한다.', 'It has incredible intellect and intuition. Whatever the situation, it remains calm and collected.'),
  ('johto', 83, 43, true, '낮에는 태양을 피하기 위해 차가운 땅속에 들어가 있다. 달빛을 쬐어 성장한다.', 'Awakened by moonlight, it roams actively at night. In the day, it stays quietly underground.'),
  ('johto', 84, 44, true, '침처럼 보이는 달콤한 꿀은 매우 끈적거려서 묻으면 좀처럼 떨어지지 않는다.', 'What appears to be drool is actually sweet honey. It is very sticky and clings stubbornly if touched.'),
  ('johto', 85, 45, true, '꽃잎이 클수록 많은 꽃가루를 만들어 내지만 머리가 무거워서 지쳐버린다고 한다.', 'It has the world’s largest petals. With every step, the petals shake out heavy clouds of toxic pollen.'),
  ('johto', 86, 182, true, '가끔 아르코가 모여서 춤을 추는 듯한 동작을 한다. 태양을 부르는 의식이라 전해진다.', 'BELLOSSOM gather at times and seem to dance. They say that the dance is a ritual to summon the sun.'),
  ('johto', 87, 96, true, '언제나 함께 잠들다 보면 가끔 옛날에 먹었던 꿈을 보여줄 때가 있다.', 'If you think that you had a good dream but you can’t remember it, a DROWZEE has probably eaten it.'),
  ('johto', 88, 97, true, '우연히 마주쳤을 때 다른 곳으로 눈을 돌리지 않으면 위험하다. 손에 든 추로 잠재워 버린다.', 'When it is very hungry, it puts humans it meets to sleep, then it feasts on their dreams.'),
  ('johto', 89, 63, true, '잠이 든 상태에서 순간이동이 가능하다. 깊이 잠들수록 먼 곳으로 이동한다고 한다.', 'It senses impending attacks and teleports away to safety before the actual attacks can strike.'),
  ('johto', 90, 64, true, '염동력의 위력은 절대적이다. 진화에 대비하여 이마에 있는 별에 사이코 파워를 비축하고 있다.', 'It possesses strong spiritual power. The more danger it faces, the stronger its psychic power.'),
  ('johto', 91, 65, true, '강력한 초능력을 구사한다. 양손에 든 숟가락은 그 힘으로 만들어낸 것이라고 한다.', 'Closing both its eyes heightens all its other senses. This enables it to use its abilities to their extremes.'),
  ('johto', 92, 132, true, '메타몽끼리 만나게 되면 상대와 똑같은 모습이 되기 위해 평소보다 격렬하게 움직인다.', 'It can transform into anything. When it sleeps, it changes into a stone to avoid being attacked.'),
  ('johto', 93, 204, true, '나무껍질을 타액으로 붙여서 몸을 두껍고 크게 만든다. 나이를 먹은 피콘은 엄청나게 크다.', 'It likes to make its shell thicker by adding layers of tree bark. The additional weight doesn’t bother it.'),
  ('johto', 94, 205, true, '먹이를 삼키는 순간에는 껍질 안의 모습이 나타나지만 그 모습을 본 자는 아직 없다.', 'Its entire body is shielded by a steel-hard shell. What lurks inside this shell is a total mystery.'),
  ('johto', 95, 29, true, '단단한 앞니로 나무열매를 깨물어 먹는다. 뿔의 끝은 수컷보다 조금 둥그스름하다.', 'The poison hidden in its small horn is extremely potent. Even a tiny scratch can have fatal results.'),
  ('johto', 96, 30, true, '무리에 위험이 닥치면 동료와 결속하여 초음파로 크게 합창한다.', 'When feeding its young, it first chews the food into a paste, then spits it out for the offspring.'),
  ('johto', 97, 31, true, '등의 가시 틈에 새끼를 태우고 달랜다. 이때는 독이 절대 나오지 않는다.', 'Its body is covered with needle-like scales. It never shows signs of shrinking from any attack.'),
  ('johto', 98, 32, true, '몸집은 작지만 용맹한 성질을 지녔다. 친한 암컷을 지키기 위해 몸을 던져 과감히 싸운다.', 'It is small, but its horn is filled with poison. It charges then stabs with the horn to inject poison.'),
  ('johto', 99, 33, true, '신경질적이고 호전적이다. 체내의 아드레날린이 증가하면 독소의 농도도 높아진다.', 'It raises its big ears to check its surroundings. If it senses anything, it attacks immediately.'),
  ('johto', 100, 34, true, '힘이 센 포켓몬이다. 굵은 꼬리와 다이아몬드도 부수는 뿔로 호쾌하게 싸운다.', 'It swings its big tail around during battle. If its foe flinches, it will charge with its sturdy body.'),
  ('johto', 101, 193, true, '눈알을 움직이지 않고 360도를 볼 수 있다. 급브레이크나 방향 전환이 특기다. 노린 먹이를 빠르게 몰아넣는다.', 'If it flaps its wings really fast, it can generate shock waves that will shatter windows in the area.'),
  ('johto', 102, 191, true, '몸에 모은 영양을 진화할 때까지 간직하기 위해 거의 움직이려 하지 않는다. 아무것도 먹지 않고 아침 이슬만 마시고 있다.', 'It may plummet from the sky. If attacked by a SPEAROW, it will violently shake its leaves.'),
  ('johto', 103, 192, true, '태양 에너지에서 영양을 만들어낸다. 기온이 높은 낮에는 활발하게 움직이고 태양이 지면 뚝 하니 움직이지 않게 된다.', 'It converts sunlight into energy. In the darkness after sunset, it closes its petals and becomes still.'),
  ('johto', 104, 102, true, '6마리가 아니면 진정하지 못한다. 1마리라도 없어지면 바로 도망태세가 된다.', 'Their shells are very durable. Even if they crack, they can survive without spilling their contents.'),
  ('johto', 105, 103, true, '3개의 머리가 똘똘 뭉쳐서 쏘는 사이코 파워는 강력하다. 날씨가 흐리면 움직임이 둔하다.', 'Its three heads think independently. However, they are friendly and never appear to squabble.'),
  ('johto', 106, 185, true, '습격당하지 않도록 나무 흉내를 낸다. 물에 약하기 때문에 비가 내리면 어느 틈에 모습을 감춰버린다.', 'Although it always pretends to be a tree, its composition appears more similar to rock than to vegetation.'),
  ('johto', 107, 202, true, '새까만 꼬리를 숨기기 위해 어둠 속에서 은밀히 지내고 있다. 자신이 먼저 공격하는 일은 없다.', 'It hates light and shock. If attacked, it inflates its body to build up its counterstrike.'),
  ('johto', 108, 48, true, '레이더 역할을 하는 큰 눈은 밝은 곳에서 보면 작은 눈이 모여서 이루어진 것임을 알 수 있다.', 'Its eyes also function as radar units. It catches and eats small bugs that hide in darkness.'),
  ('johto', 109, 49, true, '날개의 인분은 몸에 묻으면 좀처럼 떨어지지 않는다. 게다가 거기에서 독성분이 스며든다.', 'When it attacks, it flaps its large wings violently to scatter its poisonous powder all around.'),
  ('johto', 110, 123, true, '숲속에서 많은 나무가 베인 채 쓰러져 있는 장소를 발견했다면 그곳은 스라크의 영역이다.', 'It slashes through grass with its sharp scythes, moving too fast for the human eye to track.'),
  ('johto', 111, 212, true, '몸은 가늘지만 공격력은 무시무시하다. 몸의 근육도 금속으로 되어 있다.', 'It swings its eye-patterned pincers up to scare its foes. This makes it look like it has three heads.'),
  ('johto', 112, 127, true, '뿔로 먹이를 찔러 넣어 그대로 두 동강으로 만들거나 강제로 던져버린다.', 'With its pincer horns, it digs burrows to sleep in at night. In the morning, damp soil clings to its body.'),
  ('johto', 113, 214, true, '자신 몸무게의 100배에 달하는 무게도 거뜬히 들어 올리는 괴력을 자랑하는 포켓몬이다.', 'This powerful Pokémon thrusts its prized horn under its enemies’ bellies, then lifts and throws them.'),
  ('johto', 114, 109, true, '오염된 공기를 좋아한다. 옛날 가라르지방에는 지금보다 많은 또가스가 있었다고 한다.', 'Its thin, filmy body is filled with gases that cause constant sniffles, coughs and teary eyes.'),
  ('johto', 115, 110, true, '가라르의 또도가스보다 공기를 흡입하는 힘은 조금 약하지만 내뿜는 독소는 강력하다.', 'If one of the twin KOFFING inflates, the other one deflates. It constantly mixes its poisonous gases.'),
  ('johto', 116, 88, true, '진흙이 뭉쳐져서 태어났다. 악취 때문에 건드릴 엄두가 안 나고 지나간 자리에는 풀 한 포기 나지 않는다.', 'As it moves, it loses bits of its body, from which new GRIMER emerge. This worsens the stench around it.'),
  ('johto', 117, 89, true, '악취가 심하다! 기절할 정도로 강렬하지만 질뻐기는 코가 퇴화해서 냄새를 맡지 못한다.', 'They love to gather in smelly areas where sludge accumulates, making the stench around them worse.'),
  ('johto', 118, 81, true, '전기를 먹으며 살아간다. 좌우의 유닛에서 전기자석파를 방사하며 하늘을 난다.', 'It is attracted by electromagnetic waves. It may approach Trainers if they are using their Pokégear.'),
  ('johto', 119, 82, true, '강한 자력을 끊임없이 발산한다. 레어코일이 접근하면 대부분의 컴퓨터에 이상 현상이 발생한다.', 'Three MAGNEMITE are linked by a strong magnetic force. Earaches will occur if you get too close.'),
  ('johto', 120, 100, true, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'It rolls to move. If the ground is uneven, a sudden jolt from hitting a bump can cause it to explode.'),
  ('johto', 121, 101, true, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'It is dangerous. If it has too much electricity and has nothing to do, it amuses itself by exploding.'),
  ('johto', 122, 190, true, '나무 위에서 먹이를 찾는다. 좋아하는 달콤아를 발견하면 흥분해서 덤벼든다.', 'Its tail is so powerful that it can use it to grab a tree branch and hold itself up in the air.'),
  ('johto', 123, 209, true, '겉보기와 다르게 겁쟁이라 다른 강아지포켓몬과 함께 있으면 괴롭힘을 당할 때도 있다.', 'Although it looks frightening, it is actually kind and affectionate. It is very popular among women.'),
  ('johto', 124, 210, true, '젊은 여성에게 인기가 많지만 겁쟁이인데다가 섬세하기 때문에 지킴이로는 무능하다.', 'It is actually timid and easily spooked. If attacked, it flails about to fend off its attacker.'),
  ('johto', 125, 37, true, '6개의 꼬리는 자라면서 털의 결이 좋아지며 아름다워진다. 안으면 살짝 따듯하다.', 'As it develops, its single white tail gains color and splits into six. It is quite warm and cuddly.'),
  ('johto', 126, 38, true, '머리가 좋고 집념이 강하다. 장난으로 꼬리를 잡으면 1000년 동안 화를 입는다고 한다.', 'Some legends claim that each of its nine tails has its own unique type of special mystical power.'),
  ('johto', 127, 58, true, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'It has a brave and trustworthy nature. It fearlessly stands up to bigger and stronger foes.'),
  ('johto', 128, 59, true, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'This legendary Chinese Pokémon is considered magnificent. Many people are enchanted by its grand mane.'),
  ('johto', 129, 234, true, '멋지게 생긴 뿔은 미술품으로 비싸게 팔리기 때문에 멸종 직전까지 남획됐었던 포켓몬이다.', 'The curved antlers subtly change the flow of air to create a strange space where reality is distorted.'),
  ('johto', 130, 183, true, '물을 잘 튕겨내는 털은 차가운 바다에 있다가 나와도 금방 말라서 춥지 않다.', 'The tip of its tail, which contains oil that is lighter than water, lets it swim without drowning.'),
  ('johto', 131, 184, true, '공기로 가득 찬 거품을 만든다. 루리리가 강에서 놀 때는 이 거품으로 감싸준다.', 'By keeping still and listening intently, it can tell what is in even wild, fast-moving rivers.'),
  ('johto', 132, 50, true, '얕은 땅속을 이동한다. 굴을 파며 다닌 곳은 지면이 솟아 있기 때문에 바로 알 수 있다.', 'Its skin is very thin. If it is exposed to light, its blood heats up, causing it to grow weak.'),
  ('johto', 133, 51, true, '지하 100km까지 파고들 수 있는 파워를 간직한 세쌍둥이 디그다. 땅 밑은 아무도 모른다.', 'Its three heads bob separately up and down to loosen the soil nearby, making it easier for it to burrow.'),
  ('johto', 134, 56, true, '몸이 가벼워 나무 위에서 생활한다. 사소한 일로 기분이 나빠져 주변에 있는 것에 덤벼든다.', 'It is extremely ill-tempered. Groups of them will attack any handy target for no reason.'),
  ('johto', 135, 57, true, '주위에 아무도 없을 때만은 화를 내지 않고 있다. 그러나 그 모습을 보기가 어렵다.', 'If approached while asleep, it may awaken and angrily give chase in a groggy state of semi-sleep.'),
  ('johto', 136, 52, true, '이마의 금화가 더러워지지 않도록 바지런히 얼굴을 씻는다. 가라르의 나옹과는 사이가 나쁘다.', 'It is fascinated by round objects. It can’t stop playing with them until it tires and falls asleep.'),
  ('johto', 137, 53, true, '움직임은 우아하고 품위 있다. 야만스러운 나이킹과는 잘 맞지 않아 서로를 멸시한다.', 'Many adore it for its sophisticated air. However, it will lash out and scratch for little reason.'),
  ('johto', 138, 54, true, '스트레스가 쌓이면 두통이 심해진다. 강력한 염동력으로 주위를 압도한다.', 'It has mystical powers but doesn’t recall that it has used them. That is why it always looks puzzled.'),
  ('johto', 139, 55, true, '강을 더럽힌 사람을 물속으로 끌어들여 데려간다는 옛날이야기가 전해져 오고 있다.', 'When it swims at full speed using its long, webbed limbs, its forehead somehow begins to glow.'),
  ('johto', 140, 66, true, '언제나 파워풀하다. 체력이 남아돌기 때문에 심심풀이로 바위를 들어 올리며 더 강해진다.', 'Always brimming with power, it passes time by lifting boulders. Doing so makes it even stronger.'),
  ('johto', 141, 67, true, '지치지 않는 강인한 육체를 가졌다. 무거운 물건을 옮기는 등의 일을 돕는다.', 'It always goes at its full power, but this very tough and durable Pokémon never gets tired.'),
  ('johto', 142, 68, true, '4개의 팔은 생각하는 것보다 빠르게 반사적으로 움직이며 여러 발의 펀치를 날린다.', 'It quickly swings its four arms to rock its opponents with ceaseless punches and chops from all angles.'),
  ('johto', 143, 236, true, '만만한 상대를 발견하면 바로 공격해오기 때문에 몸집이 작아도 방심은 할 수 없다.', 'It is always bursting with energy. To make itself stronger, it keeps on fighting even if it loses.'),
  ('johto', 144, 106, true, '다리를 자유자재로 늘이고 줄인다. 상대가 멀리 떨어져 있어도 다리를 늘여서 차올릴 수 있다.', 'This amazing Pokémon has an awesome sense of balance. It can kick in succession from any position.'),
  ('johto', 145, 107, true, '공기마저 베어 가르는 펀치. 하지만 3분간 공격하면 잠시 쉬고 싶어하는 것 같다.', 'Its punches slice the air. However, it seems to need a short break after fighting for three minutes.'),
  ('johto', 146, 237, true, '물구나무를 서서 상대의 타이밍을 흐트러뜨리고 그 틈에 화려한 발차기를 먹인다.', 'If you are enchanted by its smooth, dance-like kicks, you may get a closer experience with one than you’d like.'),
  ('johto', 147, 203, true, '꼬리의 뇌는 생각을 할 수 없을 정도로 작지만 자지 않아도 괜찮아서 24시간 주변을 계속 망보고 있다.', 'Its tail has a small brain of its own. Beware! If you get close, it may react to your scent by biting.'),
  ('johto', 148, 128, true, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'They fight each other by locking horns. The herd’s protector takes pride in its battle-scarred horns.'),
  ('johto', 149, 241, true, '매일 우유를 짜지 않으면 컨디션이 나빠진다. 우유의 맛은 계절에 따라 다르다.', 'Its milk is packed with nutrition, making it the ultimate beverage for the sick or weary.'),
  ('johto', 150, 240, true, '화산 주위에 살고 있다. 하루를 마칠 때에는 마그마에 잠겨 피로를 푼다.', 'Each and every time it inhales and exhales, hot embers dribble from its mouth and nostrils.'),
  ('johto', 151, 126, true, '온몸이 늘 불타고 있다. 화재를 일으키는 원인 중 하나로 두려움의 대상이 되고 있다.', 'It dislikes cold places, so it blows scorching flames to make the environment suitable for itself.'),
  ('johto', 152, 238, true, '호기심이 왕성한 포켓몬이다. 뭐든지 입술에 대보고 좋은지 싫은지 판단한다.', 'Its lips are the most sensitive part of its body. It always uses its lips first to examine things.'),
  ('johto', 153, 124, true, '가라르에는 아름답고 섬세한 울음소리를 가진 루주라가 많아서 팬도 있을 정도다.', 'It rocks its body rhythmically. It appears to alter the rhythm depending on how it is feeling.'),
  ('johto', 154, 239, true, '아직 전기를 모으는 게 서툴다. 전기를 먹기 위해 민가에 숨어들어 콘센트를 찾는다.', 'It rotates its arms to generate electricity, but it tires easily, so it only charges up a little bit.'),
  ('johto', 155, 125, true, '폭풍이 치면 높은 나무 주위에 모여 번개가 떨어지기를 가만히 기다린다.', 'Electricity runs across the surface of its body. In darkness, its entire body glows a whitish-blue.'),
  ('johto', 156, 122, true, '팬터마임이 특기다. 손가락에서 내보내는 파동으로 벽을 만들어 갖은 공격으로부터 몸을 지킨다.', 'A skilled mime from birth, it gains the ability to create invisible objects as it matures.'),
  ('johto', 157, 235, true, '꼬리 끝에서 나오는 체액으로 마크를 그린다. 마크에 따라서는 마니아에게 비싼 값에 거래된다.', 'A special fluid oozes from the tip of its tail. It paints the fluid everywhere to mark its territory.'),
  ('johto', 158, 83, true, '식물의 줄기로 싸운다. 줄기를 휘두르는 방식에 따라 몇 종류의 유파가 있는 듯하다.', 'If anyone tries to disturb where the essential plant stalks grow, it uses its own stalk to thwart them.'),
  ('johto', 159, 177, true, '날개가 아직 잘 발달하지 못해서 점프하듯 이동한다. 항상 뭔가를 바라보고 있다.', 'Because its wings aren’t yet fully grown, it has to hop to get around. It is always staring at something.'),
  ('johto', 160, 178, true, '과거와 미래를 내다볼 수 있다. 매일 태양의 움직임을 관찰하는 이상한 포켓몬이다.', 'They say that it stays still and quiet because it is seeing both the past and future at the same time.'),
  ('johto', 161, 211, true, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'To fire its poison spikes, it must inflate its body by drinking over 2.6 gallons of water all at once.'),
  ('johto', 162, 72, true, '몸의 대부분이 수분이어서 바닷속에서는 물과 동화되어 매우 구분하기 힘들다.', 'When the tide goes out, dehydrated TENTACOOL remains can be found washed up on the shore.'),
  ('johto', 163, 73, true, '80개의 촉수는 자유롭게 늘어났다가 줄어든다. 그물처럼 펼쳐서 먹이를 잡고 독바늘로 찌른다.', 'Its 80 tentacles absorb water and stretch almost endlessly to constrict its prey and enemies.'),
  ('johto', 164, 98, true, '위험이 닥치면 입에서 뿜어내는 거품으로 전신을 감싸서 몸을 크게 보이려고 한다.', 'If it senses danger approaching, it cloaks itself with bubbles from its mouth so it will look bigger.'),
  ('johto', 165, 99, true, '큰 집게는 뛰어난 파괴력을 지녔지만 너무 무거워서 싸우지 않을 때는 거추장스럽다.', 'It can hardly lift its massive, overgrown pincer. The pincer’s size makes it difficult to aim properly.'),
  ('johto', 166, 213, true, '항아리 같은 등껍질 속에 모은 나무열매는 어느샌가 걸쭉한 주스로 변한다.', 'The berries it stores in its vase-like shell decompose and become a gooey liquid.'),
  ('johto', 167, 120, true, '물고기포켓몬에게 물리곤 하지만 몸이 찢겨도 금방 재생되기 때문에 신경 쓰지 않는다.', 'At night, the middle of its body slowly flickers with the same rhythm as a human heartbeat.'),
  ('johto', 168, 121, true, '몸을 고속으로 회전시켜 바다를 헤엄치며 작은 플랑크톤을 흡수한다.', 'The middle section of its body is called the core. It glows in a different color each time it is seen.'),
  ('johto', 169, 90, true, '단단한 껍데기는 어떤 공격도 튕겨낸다. 껍데기를 열었을 때 안쪽을 공격당하는 것에는 약하다.', 'It swims facing backward by opening and closing its two-piece shell. It is surprisingly fast.'),
  ('johto', 170, 91, true, '한번 껍질을 닫아버리면 어떤 괴력의 소유자도 여는 것은 불가능하다.', 'Once it slams its shell shut, it is impossible to open, even by those with superior strength.'),
  ('johto', 171, 222, true, '따뜻한 바다에 서식한다. 태고에는 가라르 근해에서도 많은 수가 서식했었다.', 'It continuously sheds and grows. The tip of its head is prized as a treasure because of its beauty.'),
  ('johto', 172, 223, true, '빨판처럼 변화한 등지느러미로 만타인에게 달라붙어 먹다 남은 것을 얻어먹고 있다.', 'It has superb accuracy. The water it shoots out can strike moving prey from more than 300 feet away.'),
  ('johto', 173, 224, true, '머리가 돌처럼 단단하다. 빨판이 붙어 있는 다리를 휘감아 끊임없이 머리로 세게 때린다.', 'It traps foes with the suction cups on its tentacles, then smashes them with its rock-hard head.'),
  ('johto', 174, 170, true, '어두운 해저에서는 항상 깜빡거리는 촉수의 빛이 유일한 통신 수단이다.', 'It shoots positive and negative electricity between the tips of its two antennae and zaps its enemies.'),
  ('johto', 175, 171, true, '강한 빛을 발산해 먹이의 눈을 멀게 한다. 허점을 보이면 전격을 먹인다.', 'The light it emits is so bright that it can illuminate the sea’s surface from a depth of over three miles.'),
  ('johto', 176, 86, true, '얼어붙을 정도로 추운 곳을 좋아한다. 영하 10도 정도의 물속에서 기분 좋게 헤엄친다.', 'Although it can’t walk well on land, it is a graceful swimmer. It especially loves being in frigid seas.'),
  ('johto', 177, 87, true, '온몸이 눈처럼 새하얗다. 추위에 강해 얼음이 떠 있는 바다도 기운차게 헤엄쳐 다닌다.', 'Its streamlined body has little drag in water. The colder the temperature, the friskier it gets.'),
  ('johto', 178, 108, true, '벌레포켓몬이 주된 먹이다. 긴 혀로 상대를 핥아 마비시킨 후 통째로 삼킨다.', 'Its tongue has well-developed nerves that run to the very tip, so it can be deftly manipulated.'),
  ('johto', 179, 114, true, '덩굴은 독특한 향이 난다. 가라르 일부 지역에서는 허브로 사용되고 있다.', 'The vines that cloak its entire body are always jiggling. They effectively unnerve its foes.'),
  ('johto', 180, 133, true, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'It has the ability to alter the composition of its body to suit its surrounding environment.'),
  ('johto', 181, 134, true, '몸의 세포 구조가 물 분자와 닮았다. 물에 녹으면 보이지 않는다.', 'When VAPOREON’s fins begin to vibrate, it is a sign that rain will come within a few hours.'),
  ('johto', 182, 135, true, '공기 중의 마이너스 이온을 빨아들여 약 10000볼트의 전기를 내뱉을 수 있다.', 'It concentrates the weak electric charges emitted by its cells and launches wicked lightning bolts.'),
  ('johto', 183, 136, true, '들이마신 공기 중 일부는 체내의 불꽃 주머니로 보내져 1700도의 불꽃이 된다.', 'It stores some of the air it inhales in its internal flame pouch, which heats it to over 3,000 degrees Fahrenheit.'),
  ('johto', 184, 196, true, '이마의 구슬에서 사이코 파워를 방사해서 싸운다. 파워가 다하면 구슬의 색이 흐려진다.', 'It uses the fine hair that covers its body to sense air currents and predict its enemy’s actions.'),
  ('johto', 185, 197, true, '보름달이 뜬 밤이나 흥분했을 때 전신의 고리 무늬가 노랗게 빛난다.', 'When agitated, this Pokémon protects itself by spraying poisonous sweat from its pores.'),
  ('johto', 186, 116, true, '물속에서 춤추듯이 헤엄쳐 소용돌이를 만든다. 동료와 소용돌이의 크기를 겨루며 논다.', 'If attacked by a larger enemy, it quickly swims to safety by adeptly controlling its well-developed dorsal fin.'),
  ('johto', 187, 117, true, '입은 가늘지만 흡인력은 강하다. 입보다 큰 먹이도 순식간에 빨아들여 먹는다.', 'An examination of its cells revealed the presence of a gene not found in HORSEA. It became a hot topic.'),
  ('johto', 188, 230, true, '떨어진 비늘은 왕족에게 헌상될 정도의 최상품으로 심오한 빛을 띤다.', 'It is said that it usually hides in underwater caves. It can create whirlpools by yawning.'),
  ('johto', 189, 207, true, '소리 내지 않고 미끄러지듯 활공한다. 양손의 커다란 손톱과 발의 발톱으로 먹이의 얼굴에 달라붙어 독침을 찌른다.', 'It flies straight at its target’s face, then clamps down on the startled victim to inject poison.'),
  ('johto', 190, 225, true, '자신의 먹이를 사람이나 포켓몬에게 나눠주는 습성이 있어 언제나 먹이를 찾아다닌다.', 'It carries food all day long. There are tales about lost people who were saved by its stored food.'),
  ('johto', 191, 220, true, '좋은 냄새를 맡으면 뒷일을 생각하지 않고 냄새 나는 방향으로 대시해버린다.', 'It rubs its snout on the ground to find and dig up food. It sometimes discovers hot springs.'),
  ('johto', 192, 221, true, '4개의 다리는 짧지만 발굽이 넓고 거칠거칠하므로 눈 위도 미끄러지지 않고 걸을 수 있다.', 'Because the long hair all over its body obscures its sight, it just keeps charging repeatedly.'),
  ('johto', 193, 216, true, '꿀이 밴 손바닥을 핥고 있다. 깜지곰의 꿀은 과일과 독침붕이 모은 꽃가루가 혼합되어 만들어진다.', 'If it finds honey, its crescent mark glows. It always licks its paws because they’re soaked with honey.'),
  ('johto', 194, 217, true, '숲 속에는 링곰이 먹이를 수집하는 큰 나무나 시냇가가 여기저기에 있다고 한다. 매일 먹이를 모으며 숲을 걷는다.', 'Although it is a good climber, it prefers to snap trees with its forelegs and eat fallen berries.'),
  ('johto', 195, 231, true, '긴 코를 써서 물을 끼얹는다. 동료가 모여들면 서로 물을 끼얹는다. 흠뻑 젖은 몸을 물가에서 말린다.', 'It swings its long snout around playfully, but because it is so strong, that can be dangerous.'),
  ('johto', 196, 232, true, '단단한 몸으로 부딪치면 집도 부서진다. 그 힘을 이용해 산길을 막고 있는 토사를 치우는 일을 돕는다.', 'It has sharp, hard tusks and a rugged hide. Its tackle is strong enough to knock down a house.'),
  ('johto', 197, 226, true, '여유롭게 바다를 헤엄친다. 먹다 남은 음식을 노린 총어가 달라붙어 있어도 신경 쓰지 않는다.', 'As it majestically swims, it doesn’t care if REMORAID attach to it for scavenging its leftovers.'),
  ('johto', 198, 227, true, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'Its sturdy wings look heavy, but they are actually hollow and light, allowing it to fly freely in the sky.'),
  ('johto', 199, 84, true, '날개가 짧아서 하늘을 나는 것은 서투르지만 대신 발달한 다리로 빠르게 달릴 수 있다.', 'By alternately raising and lowering its two heads, it balances itself to be more stable while running.'),
  ('johto', 200, 85, true, '두두의 머리 중 한 쪽이 분열한 변종. 초원을 시속 60km로 달린다.', 'It collects data and plans three times as wisely, but it may think too much and fall into a state of immobility.'),
  ('johto', 201, 77, true, '포니타에게 인정받으면 타오르는 갈기를 만져도 뜨거움을 느끼지 않게 된다.', 'It is a weak runner immediately after birth. It gradually becomes faster by chasing after its parents.'),
  ('johto', 202, 78, true, '가장 발이 빠른 날쌩마가 리더가 되어 무리가 갈 장소나 달리는 속도를 정한다.', 'At full gallop, its four hooves barely touch the ground because it moves so incredibly fast.'),
  ('johto', 203, 104, true, '죽은 어미의 뼈를 머리에 쓰고 있다. 어미의 꿈을 꾸고 울기도 하지만 눈물을 흘릴 때마다 강해진다.', 'If it is sad or lonely, the skull it wears shakes and emits a plaintive and mournful sound.'),
  ('johto', 204, 105, true, '진화로 인해 쓰고 있던 어미의 뼈는 일체화되었고 성격은 더욱 난폭해졌다.', 'It has been seen pounding boulders with the bone it carries in order to tap out messages to others.'),
  ('johto', 205, 115, true, '새끼가 없는 캥카가 조난한 사람의 아이를 길렀다는 기록이 있다.', 'If it is safe, the young gets out of the belly pouch to play. The adult keeps a close eye on the youngster.'),
  ('johto', 206, 111, true, '한 가지만 기억할 수 있다. 돌진하기 시작하면 이유가 무엇이었든 금방 잊어버린다.', 'It is inept at turning because of its four short legs. It can only charge and run in one direction.'),
  ('johto', 207, 112, true, '전신을 갑옷 같은 피부로 보호하고 있다. 2000도의 마그마 속에서도 살 수 있다.', 'Its rugged hide protects it from even the heat of lava. However, the hide also makes it insensitive.'),
  ('johto', 208, 198, true, '보스를 위해 반짝반짝 빛나는 것을 찾고 있다. 불길한 존재로 여겨 몹시 싫어하는 사람도 많다.', 'Feared and loathed by many, it is believed to bring misfortune to all those who see it at night.'),
  ('johto', 209, 228, true, '동이 트기 전에 기분 나쁜 울음을 반복하여 자신들 무리의 존재를 어필한다.', 'It uses different kinds of cries for communicating with others of its kind and for pursuing its prey.'),
  ('johto', 210, 229, true, '기분 나쁜 울음소리가 특징이다. 옛날 사람들은 지옥에서 온 사자라고 여겨 두려워했다.', 'If you are burned by the flames it shoots from its mouth, the pain will never go away.'),
  ('johto', 211, 218, true, '몸 안에는 혈액 대신 필요한 영양과 산소를 운반하기 위해 작열하는 마그마가 순환되고 있다.', 'It never sleeps. It has to keep moving because if it stopped, its magma body would cool and harden.'),
  ('johto', 212, 219, true, '체온이 약 1만 도나 돼서 빗방울이 몸에 닿으면 수증기가 자욱하게 피어나 주변이 깊은 안개에 둘러싸인다고 한다.', 'The shell on its back is just skin that has cooled and hardened. It breaks easily with a slight touch.'),
  ('johto', 213, 215, true, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'Its paws conceal sharp claws. If attacked, it suddenly extends the claws and startles its enemy.'),
  ('johto', 214, 200, true, '사람이 울부짖는 소리를 흉내 내 모두를 겁주고 기뻐한다. 담력이 강한 상대는 좋아하지 않는다.', 'It likes playing mischievous tricks, such as screaming and wailing to startle people at night.'),
  ('johto', 215, 137, true, '근래에는 컴퓨터 공간에서 대활약한다. 수상한 데이터가 없는지 체크하며 돌아다닌다.', 'It is a manmade Pokémon. Since it doesn’t breathe, people are eager to try it in any environment.'),
  ('johto', 216, 233, true, 'AI 기능을 탑재한 결과 폴리곤2끼리만 통하는 수수께끼의 언어로 말하기 시작했다.', 'This upgraded version of PORYGON is designed for space exploration. It can’t fly, however.'),
  ('johto', 217, 113, true, '원래 움직임이 둔했지만 알을 노리는 자들로부터 지켜내기 위해 도주 속도가 빨라졌다.', 'It walks carefully to prevent its egg from breaking. However, it is extremely fast at running away.'),
  ('johto', 218, 242, true, '행복이 가득 찬 신비한 알을 낳는다. 먹은 사람은 누구에게나 친절해진다고 한다.', 'Anyone who takes even one taste of BLISSEY’s egg becomes unfailingly caring and pleasant to everyone.'),
  ('johto', 219, 131, true, '추위에 강해서 얼음 바다에서도 끄떡없다. 피부는 매끈매끈하고 조금 차갑다.', 'They have gentle hearts. Because they rarely fight, many have been caught. Their number has dwindled.'),
  ('johto', 220, 138, true, '멸종한 고대의 포켓몬이다. 10개의 다리로 물을 가르며 떠다니듯 헤엄친다.', 'Revived from an ancient fossil, this Pokémon uses air stored in its shell to sink and rise in water.'),
  ('johto', 221, 139, true, '날카로운 이빨은 바위도 부수지만 촉수가 닿는 범위 안의 먹이만 공격할 수 있다.', 'Apparently, it cracked SHELLDER’s shell with its sharp fangs and sucked out the insides.'),
  ('johto', 222, 140, true, '멸종되었다는 이야기가 있지만 일부 지역에서는 제법 많이 목격되는 듯하다.', 'On rare occasions, some have been found as fossils which they became while hiding on the ocean floor.'),
  ('johto', 223, 141, true, '멸종한 이유는 불명확하다. 따듯한 바다에 살고 있던 난폭한 고대의 포켓몬이다.', 'In the water, it tucks in its limbs to become more compact, then it wiggles its shell to swim fast.'),
  ('johto', 224, 142, true, '톱 같은 이빨은 강철포켓몬의 피부도 갈기갈기 베어 가른다.', 'A vicious Pokémon from the distant past, it appears to have flown by spreading its wings and gliding.'),
  ('johto', 225, 143, true, '위장이 튼튼해서 곰팡이가 피거나 썩은 것을 먹어도 배탈이 나지 않는다.', 'What sounds like its cry may actually be its snores or the rumblings of its hungry belly.'),
  ('johto', 226, 1, true, '태어나서 얼마 동안 등의 씨앗에 담긴 영양을 섭취하며 자란다.', 'The seed on its back is filled with nutrients. The seed grows steadily larger as its body grows.'),
  ('johto', 227, 2, true, '햇빛을 받을수록 몸에 힘이 솟아나 등의 꽃봉오리가 자라난다.', 'Exposure to sunlight adds to its strength. Sunlight also makes the bud on its back grow larger.'),
  ('johto', 228, 3, true, '꽃에서 황홀한 향기가 퍼져 나와 싸우는 자의 기분을 달래준다.', 'By spreading the broad petals of its flower and catching the sun’s rays, it fills its body with power.'),
  ('johto', 229, 4, true, '태어날 때부터 꼬리에 불꽃이 타오르고 있다. 불꽃이 꺼지면 생명도 다하고 만다.', 'The flame on its tail shows the strength of its life force. If it is weak, the flame also burns weakly.'),
  ('johto', 230, 5, true, '싸움으로 기분이 고조되면 작열하는 불꽃을 뿜으며 주변을 태워버린다.', 'It is very hotheaded by nature, so it constantly seeks opponents. It calms down only when it wins.'),
  ('johto', 231, 6, true, '지상 1400m까지 날개를 사용해 날 수 있다. 고열의 불꽃을 내뿜는다.', 'If CHARIZARD becomes furious, the flame at the tip of its tail flares up in a light blue shade.'),
  ('johto', 232, 7, true, '위험해지면 등껍질에 손발을 감추고 몸을 지키면서 입에서 물을 내뿜는다.', 'The shell is soft when it is born. It soon becomes so resilient, prodding fingers will bounce off it.'),
  ('johto', 233, 8, true, '탐스러운 귀와 꼬리를 능숙하게 다뤄서 수중에서의 밸런스를 유지한다.', 'It is a well-established symbol of longevity. If its shell has algae on it, that WARTORTLE is very old.'),
  ('johto', 234, 9, true, '등껍질의 로켓포에서 뿜어져 나오는 제트 수류는 두꺼운 철판도 뚫는다.', 'It deliberately makes itself heavy so it can withstand the recoil of the water jets it fires.'),
  ('johto', 235, 144, true, '얼음을 자유자재로 조종하는 힘을 가졌다. 영구 동토의 설산에 살고 있다고 한다.', 'The magnificent, seemingly translucent wings of this legendary bird Pokémon are said to be made of ice.'),
  ('johto', 236, 145, true, '날개를 비비대면 바로 천둥이 친다고 전해지는 전설의 새포켓몬이다.', 'This legendary bird Pokémon causes savage thunderstorms by flapping its glittering wings.'),
  ('johto', 237, 146, true, '아름답게 타오르는 날개로 산길을 비춰 조난자를 도왔다고 전해져 오고 있다.', 'This legendary Pokémon scatters embers with every flap of its wings. It is a thrilling sight to behold.'),
  ('johto', 238, 243, true, '번개의 스피드가 깃들어 있는 포켓몬이다. 그 울음소리는 번개가 내리쳤을 때처럼 공기를 떨리게 하며 대지를 흔든다.', 'The rain clouds it carries let it fire thunderbolts at will. They say that it descended with lightning.'),
  ('johto', 239, 244, true, '마그마의 정열이 깃들어 있는 포켓몬이다. 화산 분화 속에서 태어났다고 여겨지며 모든 것을 태워버리는 불꽃을 뿜어 올린다.', 'Volcanoes erupt when it barks. Unable to contain its sheer power, it races headlong around the land.'),
  ('johto', 240, 245, true, '솟아나는 물의 부드러움이 깃들어 있는 포켓몬이다. 흐르는 듯한 몸놀림으로 대지를 달려 탁해진 물을 맑게 하는 힘을 지녔다.', 'Said to be the embodiment of north winds, it can instantly purify filthy, murky water.'),
  ('johto', 241, 147, true, '오랫동안 환상이라고 불렸다. 이마에 있는 작은 돌기는 성장하고 있는 뿔이다.', 'It is born large to start with. It repeatedly sheds its skin as it steadily grows longer.'),
  ('johto', 242, 148, true, '꼬리의 구슬에 힘을 모아 날씨를 조종한다. 오라에 둘러싸인 모습은 신비롭다.', 'They say that if it emits an aura from its whole body, the weather will begin to change instantly.'),
  ('johto', 243, 149, true, '바다의 화신이라고 불린다. 망나뇽 형태의 조각상을 뱃머리에 두는 배도 많다.', 'It is said that this Pokémon constantly flies over the immense seas and rescues drowning people.'),
  ('johto', 244, 246, true, '흙을 먹으며 살고 있다. 큰 산 하나를 다 먹으면 성장을 위해 잠자기 시작한다.', 'It feeds on soil. After it has eaten a large mountain, it falls asleep so it can grow.'),
  ('johto', 245, 247, true, '번데기지만 가만히 있지 않는다. 단단한 껍질 안에는 이미 팔다리가 만들어져 있다.', 'Its shell is as hard as sheet rock, and it is also very strong. Its thrashing can topple a mountain.'),
  ('johto', 246, 248, true, '지축을 울리면서 걸으면 큰 산조차 무너지며 주변의 지형은 변해버린다.', 'Its body can’t be harmed by any sort of attack, so it is very eager to make challenges against enemies.'),
  ('johto', 247, 249, true, '가벼운 날갯짓만으로도 민가를 날려버릴 만한 파괴력을 지니고 있어서 해저에서 사람들 몰래 살게 됐다.', 'It is said that it quietly spends its time deep at the bottom of the sea because its powers are too strong.'),
  ('johto', 248, 250, true, '빛이 닿는 각도에 따라 일곱 빛깔로 반짝이는 깃털은 행복을 가져다준다고 한다. 무지개 끝에 산다고 전해진다.', 'Legends claim this Pokémon flies the world’s skies continuously on its magnificent, seven-colored wings.'),
  ('johto', 249, 150, true, '뮤의 유전자와 거의 같다. 하지만 크기도 성격도 무서울 정도로 다르다.', 'Because its battle abilities were raised to the ultimate level, it thinks only of defeating its foes.'),
  ('johto', 250, 151, true, '현미경으로 관찰하면 매우 짧고 가는 털이 촘촘하게 나 있다.', 'Apparently, it appears only to those people who are pure of heart and have a strong desire to see it.'),
  ('johto', 251, 251, true, '미래에서 시간을 건너 찾아왔다. 상처를 치료하고 초목에 힘을 나누어준다.', 'This Pokémon wanders across time. Grass and trees flourish in the forests in which it has appeared.')
